using Godot;
using System;

namespace ApexGP24;

public static class ProceduralMaterialFactory
{
    public static StandardMaterial3D CreateAsphaltMaterial()
    {
        var mat = new StandardMaterial3D
        {
            AlbedoColor = Colors.White,
            Roughness = 1.0f,
            Metallic = 0.06f,
            Uv1Scale = new Vector3(1.0f, 1.0f, 1.0f)
        };

        Texture2D extColor = AssetLoader3D.TryLoadTexture("Asphalt PBR",
            "res://assets/textures/asphalt_color.jpg",
            "res://assets/textures/asphalt_color.png");
        if (extColor != null)
        {
            mat.AlbedoTexture = extColor;
            Texture2D extNorm = AssetLoader3D.TryLoadTexture("Asphalt PBR",
                "res://assets/textures/asphalt_normal.jpg",
                "res://assets/textures/asphalt_normal.png");
            if (extNorm != null)
            {
                mat.NormalEnabled = true;
                mat.NormalTexture = extNorm;
                mat.NormalScale = 0.78f;
            }
            Texture2D extRough = AssetLoader3D.TryLoadTexture("Asphalt PBR",
                "res://assets/textures/asphalt_roughness.jpg",
                "res://assets/textures/asphalt_roughness.png");
            if (extRough != null) mat.RoughnessTexture = extRough;
            else mat.Roughness = 0.68f;
            return mat;
        }

        // Ultra-HD 512x512 Multi-Scale FIA Race Tarmac with dual rubbered grooves, mineral aggregate & specular sheen!
        const int sz = 512;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var roughImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(2026);
        float[,] hMap = new float[sz, sz];

        for (int y = 0; y < sz; y++)
        {
            float vWave = Mathf.Sin((y / (float)sz) * Mathf.Tau * 3.0f) * 0.012f;
            for (int x = 0; x < sz; x++)
            {
                float u = x / (float)(sz - 1);
                float grooveL = Mathf.Exp(-Mathf.Pow((u - 0.34f) * 8.2f, 2.0f)) * 0.072f;
                float grooveR = Mathf.Exp(-Mathf.Pow((u - 0.66f) * 8.2f, 2.0f)) * 0.072f;
                float grooveTotal = grooveL + grooveR;
                float fine = ((float)rng.NextDouble() - 0.5f) * 0.075f;
                float coarse = Mathf.Sin(u * 26f + vWave * 5f) * Mathf.Cos((y / (float)sz) * Mathf.Tau * 4f) * 0.014f;
                float marbles = (u < 0.14f || u > 0.86f) && rng.NextDouble() < 0.03 ? -0.05f : 0f;
                hMap[x, y] = fine + coarse + marbles;

                bool edgeLine = (u < 0.024f || u > 0.976f);
                if (edgeLine)
                {
                    img.SetPixel(x, y, new Color(0.96f, 0.97f, 0.99f));
                    roughImg.SetPixel(x, y, new Color(0.42f, 0.42f, 0.42f));
                }
                else
                {
                    float v = Mathf.Clamp(0.245f - grooveTotal + fine + coarse + marbles, 0.085f, 0.37f);
                    img.SetPixel(x, y, new Color(v, v * 1.03f, v * 1.11f));
                    float rVal = Mathf.Clamp(0.76f - grooveTotal * 3.1f + fine * 0.7f, 0.38f, 0.88f);
                    roughImg.SetPixel(x, y, new Color(rVal, rVal, rVal));
                }
            }
        }

        GenerateNormalMapFromHeight(hMap, sz, 5.8f, normImg);
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        roughImg.GenerateMipmaps();
        mat.AlbedoTexture = ImageTexture.CreateFromImage(img);
        mat.NormalEnabled = true;
        mat.NormalTexture = ImageTexture.CreateFromImage(normImg);
        mat.NormalScale = 0.68f;
        mat.RoughnessTexture = ImageTexture.CreateFromImage(roughImg);
        return mat;
    }

    public static StandardMaterial3D CreateGrassMaterial()
    {
        var mat = new StandardMaterial3D
        {
            AlbedoColor = Colors.White,
            Roughness = 0.92f,
            Metallic = 0.0f,
            Uv1Scale = new Vector3(52.0f, 52.0f, 1.0f)
        };

        Texture2D extColor = AssetLoader3D.TryLoadTexture("Grass PBR",
            "res://assets/textures/grass_color.jpg",
            "res://assets/textures/grass_color.png");
        if (extColor != null)
        {
            mat.AlbedoTexture = extColor;
            Texture2D extNorm = AssetLoader3D.TryLoadTexture("Grass PBR",
                "res://assets/textures/grass_normal.jpg",
                "res://assets/textures/grass_normal.png");
            if (extNorm != null)
            {
                mat.NormalEnabled = true;
                mat.NormalTexture = extNorm;
            }
            return mat;
        }

        const int sz = 256;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(404);
        float[,] hMap = new float[sz, sz];

        for (int y = 0; y < sz; y++)
        {
            bool stripe = ((y / 32) % 2) == 0;
            for (int x = 0; x < sz; x++)
            {
                float n = ((float)rng.NextDouble() - 0.5f) * 0.09f;
                float patch = Mathf.Sin(x * 0.05f) * Mathf.Cos(y * 0.05f) * 0.03f;
                hMap[x, y] = n + patch;
                float sBoost = stripe ? 0.026f : -0.020f;
                float r = Mathf.Clamp(0.15f + sBoost + patch + n * 0.6f, 0.06f, 0.34f);
                float g = Mathf.Clamp(0.35f + sBoost * 1.4f + patch + n, 0.14f, 0.54f);
                float b = Mathf.Clamp(0.12f + sBoost * 0.4f + n * 0.5f, 0.05f, 0.24f);
                img.SetPixel(x, y, new Color(r, g, b));
            }
        }

        GenerateNormalMapFromHeight(hMap, sz, 3.6f, normImg);
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        mat.AlbedoTexture = ImageTexture.CreateFromImage(img);
        mat.NormalEnabled = true;
        mat.NormalTexture = ImageTexture.CreateFromImage(normImg);
        mat.NormalScale = 0.50f;
        return mat;
    }

    public static StandardMaterial3D CreateGravelMaterial()
    {
        var mat = new StandardMaterial3D
        {
            AlbedoColor = Colors.White,
            Roughness = 0.94f,
            Metallic = 0.0f,
            Uv1Scale = new Vector3(1.0f, 1.0f, 1.0f)
        };

        Texture2D extColor = AssetLoader3D.TryLoadTexture("Gravel PBR",
            "res://assets/textures/gravel_color.jpg",
            "res://assets/textures/gravel_color.png");
        if (extColor != null)
        {
            mat.AlbedoTexture = extColor;
            Texture2D extNorm = AssetLoader3D.TryLoadTexture("Gravel PBR",
                "res://assets/textures/gravel_normal.jpg",
                "res://assets/textures/gravel_normal.png");
            if (extNorm != null)
            {
                mat.NormalEnabled = true;
                mat.NormalTexture = extNorm;
            }
            return mat;
        }

        const int sz = 256;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(808);
        float[,] hMap = new float[sz, sz];

        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float furrow = Mathf.Sin((x / (float)sz) * Mathf.Tau * 8.0f) * 0.065f;
                float pebble = ((float)rng.NextDouble() - 0.5f) * 0.16f;
                hMap[x, y] = furrow + pebble * 0.65f;
                float r = Mathf.Clamp(0.69f + furrow + pebble, 0.42f, 0.89f);
                float g = Mathf.Clamp(0.61f + furrow + pebble * 0.9f, 0.36f, 0.80f);
                float b = Mathf.Clamp(0.47f + furrow * 0.8f + pebble * 0.7f, 0.25f, 0.65f);
                img.SetPixel(x, y, new Color(r, g, b));
            }
        }

        GenerateNormalMapFromHeight(hMap, sz, 6.8f, normImg);
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        mat.AlbedoTexture = ImageTexture.CreateFromImage(img);
        mat.NormalEnabled = true;
        mat.NormalTexture = ImageTexture.CreateFromImage(normImg);
        mat.NormalScale = 0.85f;
        return mat;
    }

    public static StandardMaterial3D CreateCrowdMaterial()
    {
        const int w = 512;
        const int h = 256;
        var img = Image.CreateEmpty(w, h, false, Image.Format.Rgba8);
        var rng = new Random(2024);

        Color[] shirts =
        {
            new(0.88f, 0.14f, 0.14f),
            new(0.95f, 0.96f, 0.98f),
            new(0.10f, 0.44f, 0.90f),
            new(1.00f, 0.80f, 0.12f),
            new(1.00f, 0.46f, 0.04f),
            new(0.14f, 0.68f, 0.32f),
            new(0.06f, 0.76f, 0.84f),
            new(0.16f, 0.20f, 0.32f)
        };

        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++)
            {
                img.SetPixel(x, y, new Color(0.14f, 0.17f, 0.22f));
            }
        }

        for (int row = 0; row < 16; row++)
        {
            int yBase = row * 16 + 2;
            for (int x = 0; x < w; x++)
            {
                if (yBase + 13 < h) img.SetPixel(x, yBase + 13, new Color(0.05f, 0.06f, 0.09f));
                if (yBase + 14 < h) img.SetPixel(x, yBase + 14, new Color(0.09f, 0.11f, 0.15f));
            }

            for (int x = 3; x < w - 7; x += 6)
            {
                if ((x % 128) < 12)
                {
                    bool rail = (x % 128) == 5 || (x % 128) == 6;
                    Color stepCol = rail ? new Color(0.95f, 0.82f, 0.12f) : new Color(0.34f, 0.37f, 0.43f);
                    for (int dy = 0; dy < 13 && yBase + dy < h; dy++)
                    {
                        for (int dx = 0; dx < 6; dx++) img.SetPixel(x + dx, yBase + dy, stepCol);
                    }
                    continue;
                }

                if (rng.NextDouble() < 0.94)
                {
                    Color shirt = shirts[rng.Next(shirts.Length)];
                    Color skin = new Color(0.86f, 0.72f, 0.60f);
                    Color cap = shirts[rng.Next(shirts.Length)];
                    bool hasCap = rng.NextDouble() < 0.42;

                    for (int dy = 0; dy < 4 && yBase + dy < h; dy++)
                    {
                        for (int dx = 1; dx < 4; dx++)
                        {
                            img.SetPixel(x + dx, yBase + dy, (dy < 2 && hasCap) ? cap : skin);
                        }
                    }
                    for (int dy = 4; dy < 12 && yBase + dy < h; dy++)
                    {
                        for (int dx = 0; dx < 5; dx++)
                        {
                            float shade = dy > 8 ? 0.82f : 1.0f;
                            img.SetPixel(x + dx, yBase + dy, new Color(shirt.R * shade, shirt.G * shade, shirt.B * shade));
                        }
                    }
                }
            }
        }

        img.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            Roughness = 0.86f,
            Metallic = 0.0f,
            Uv1Scale = new Vector3(2.0f, 1.0f, 1.0f)
        };
    }

    public static StandardMaterial3D CreateBarrierSponsorMaterial()
    {
        const int w = 1024;
        const int h = 128;
        var img = Image.CreateEmpty(w, h, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(w, h, false, Image.Format.Rgba8);
        float[,] hMap = new float[w, h];

        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++)
            {
                int panel = x / 256;
                int lx = x % 256;
                Color bg = panel switch
                {
                    0 => new Color(0.97f, 0.80f, 0.08f), // Pirelli Yellow
                    1 => new Color(0.95f, 0.96f, 0.98f), // White Sponsor
                    2 => new Color(0.86f, 0.09f, 0.09f), // F1 Red
                    _ => new Color(0.05f, 0.44f, 0.34f)  // Aramco Emerald
                };

                float elev = 0f;
                // Galvanized steel top Armco cap & concrete bottom New-Jersey plinth
                if (y < 14)
                {
                    float sheen = 0.78f + 0.14f * Mathf.Sin((y / 14f) * Mathf.Pi);
                    bg = new Color(sheen, sheen * 1.02f, sheen * 1.06f);
                    elev = 0.35f;
                }
                else if (y > 106)
                {
                    bg = new Color(0.56f, 0.60f, 0.66f);
                    elev = 0.20f;
                }
                else
                {
                    // Corrugated steel Armco rib shadow lines + sponsor accent border
                    if (y == 18 || y == 102) bg = bg.Darkened(0.22f);
                    if (y >= 46 && y <= 76 && lx > 30 && lx < 226)
                    {
                        bool letterBlock = ((lx % 24) >= 4) && ((lx % 24) <= 20);
                        bool innerCut = (y > 54 && y < 68) && ((lx % 24) > 8 && (lx % 24) < 16);
                        if (letterBlock && !innerCut)
                        {
                            bg = (panel == 0 || panel == 1)
                                ? new Color(0.84f, 0.08f, 0.08f)
                                : new Color(0.98f, 0.99f, 1.0f);
                        }
                    }
                }

                if (lx < 4 || lx > 252)
                {
                    bg = new Color(0.16f, 0.19f, 0.24f);
                    elev = -0.3f;
                }
                img.SetPixel(x, y, bg);
                hMap[x, y] = elev;
            }
        }

        // Light normal map for panel seams & Armco rail edges
        for (int y = 0; y < h; y++)
        {
            for (int x = 0; x < w; x++)
            {
                float dx = (hMap[(x + 1) % w, y] - hMap[(x - 1 + w) % w, y]) * 1.8f;
                float dy = (hMap[x, (y + 1) % h] - hMap[x, (y - 1 + h) % h]) * 1.8f;
                Vector3 n = new Vector3(-dx, -dy, 1.0f).Normalized();
                normImg.SetPixel(x, y, new Color(n.X * 0.5f + 0.5f, n.Y * 0.5f + 0.5f, n.Z * 0.5f + 0.5f));
            }
        }

        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            NormalEnabled = true,
            NormalTexture = ImageTexture.CreateFromImage(normImg),
            NormalScale = 0.55f,
            Roughness = 0.46f,
            Metallic = 0.14f,
            CullMode = BaseMaterial3D.CullModeEnum.Disabled
        };
    }

    public static StandardMaterial3D CreateCarbonMaterial(float tileScale = 7.0f)
    {
        var mat = new StandardMaterial3D
        {
            AlbedoColor = Colors.White,
            Roughness = 0.22f,
            Metallic = 0.30f,
            ClearcoatEnabled = true,
            Clearcoat = 0.96f,
            ClearcoatRoughness = 0.09f,
            Uv1Scale = new Vector3(tileScale, tileScale, 1.0f)
        };

        Texture2D extColor = AssetLoader3D.TryLoadTexture("Carbon PBR",
            "res://assets/textures/carbon_color.jpg",
            "res://assets/textures/carbon_color.png");
        if (extColor != null)
        {
            mat.AlbedoTexture = extColor;
            Texture2D extNorm = AssetLoader3D.TryLoadTexture("Carbon PBR",
                "res://assets/textures/carbon_normal.jpg",
                "res://assets/textures/carbon_normal.png");
            if (extNorm != null)
            {
                mat.NormalEnabled = true;
                mat.NormalTexture = extNorm;
            }
            return mat;
        }

        // Ultra-Sharp 256x256 2x2 Gloss Twill Carbon Fiber (Albedo + Normal + Specular Sheen!)
        const int sz = 256;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                int cx = x / 16;
                int cy = y / 16;
                bool warp = ((cx + cy) & 3) < 2;
                float lx = (x % 16) / 15.0f;
                float ly = (y % 16) / 15.0f;
                float arch = warp
                    ? Mathf.Sin(lx * Mathf.Pi)
                    : Mathf.Sin(ly * Mathf.Pi);
                float edgeDark = (x % 16 == 0 || y % 16 == 0) ? 0.55f : 1.0f;
                float sheen = (warp ? (0.06f + 0.19f * arch) : (0.035f + 0.10f * arch)) * edgeDark;
                img.SetPixel(x, y, new Color(sheen, sheen * 1.06f, sheen * 1.18f));

                float nx = warp ? (lx - 0.5f) * 0.95f : 0f;
                float ny = warp ? 0f : (ly - 0.5f) * 0.95f;
                Vector3 n = new Vector3(nx, ny, 1.0f).Normalized();
                normImg.SetPixel(x, y, new Color(n.X * 0.5f + 0.5f, n.Y * 0.5f + 0.5f, n.Z * 0.5f + 0.5f));
            }
        }
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        mat.AlbedoTexture = ImageTexture.CreateFromImage(img);
        mat.NormalEnabled = true;
        mat.NormalTexture = ImageTexture.CreateFromImage(normImg);
        mat.NormalScale = 0.72f;
        return mat;
    }

    public static StandardMaterial3D CreateAlcantaraMaterial()
    {
        const int sz = 128;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(77);
        float[,] hMap = new float[sz, sz];

        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                bool hole = ((x % 8 == 2) && (y % 8 == 2)) || ((x % 8 == 6) && (y % 8 == 6));
                float n = ((float)rng.NextDouble() - 0.5f) * 0.04f;
                hMap[x, y] = hole ? -0.35f : n;
                float v = hole ? 0.025f : (0.105f + n);
                img.SetPixel(x, y, new Color(v, v * 1.03f, v * 1.08f));
            }
        }
        GenerateNormalMapFromHeight(hMap, sz, 3.0f, normImg);
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            NormalEnabled = true,
            NormalTexture = ImageTexture.CreateFromImage(normImg),
            NormalScale = 0.55f,
            Roughness = 0.90f,
            Metallic = 0.02f,
            Uv1Scale = new Vector3(4f, 4f, 1f)
        };
    }

    /// <summary>
    /// High-Resolution 256x256 Woven Nomex Racing Glove & Suit Fabric with Normal Map, Micro-Weave & Stitched Seams!
    /// Eliminates flat plastic shading on driver arms & hands.
    /// </summary>
    public static StandardMaterial3D CreateNomexFabricMaterial(Color baseColor, bool includeTeamStripe = false, Color? stripeColor = null, bool ribbedCuff = false)
    {
        const int sz = 256;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var normImg = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        var rng = new Random(ribbedCuff ? 313 : (includeTeamStripe ? 212 : 101));
        float[,] hMap = new float[sz, sz];

        Color stCol = stripeColor ?? new Color(0.95f, 0.97f, 1.0f);

        for (int y = 0; y < sz; y++)
        {
            float v = y / (float)(sz - 1);
            // Subtle cloth fold creases across forearm/sleeve length
            float crease = Mathf.Sin(v * Mathf.Tau * 4.5f) * 0.045f + Mathf.Sin(v * Mathf.Tau * 11.0f) * 0.015f;
            for (int x = 0; x < sz; x++)
            {
                float u = x / (float)(sz - 1);
                float weave = ribbedCuff
                    ? (Mathf.Sin((x / (float)sz) * Mathf.Tau * 32.0f) * 0.08f)
                    : ((((x / 2 + y / 2) & 1) == 0 ? 0.032f : -0.024f) + Mathf.Sin((x + y) * 0.5f) * 0.014f);
                float grain = ((float)rng.NextDouble() - 0.5f) * 0.042f;

                // Stitched longitudinal & quilted seam detail
                bool seam = (x == 64 || x == 192) || (!ribbedCuff && (y % 64 == 0));
                float seamDip = seam ? -0.16f : 0f;

                hMap[x, y] = weave + crease * 1.6f + grain * 0.6f + seamDip;

                Color c = baseColor;
                if (includeTeamStripe && (u > 0.44f && u < 0.56f))
                {
                    bool edgePin = (u < 0.455f || u > 0.545f);
                    c = edgePin ? new Color(0.06f, 0.08f, 0.12f) : stCol;
                }

                float mult = Mathf.Clamp(0.96f + weave + crease + grain + (seam ? -0.14f : 0f), 0.68f, 1.18f);
                img.SetPixel(x, y, new Color(
                    Mathf.Clamp(c.R * mult, 0f, 1f),
                    Mathf.Clamp(c.G * mult, 0f, 1f),
                    Mathf.Clamp(c.B * mult, 0f, 1f)));
            }
        }

        GenerateNormalMapFromHeight(hMap, sz, ribbedCuff ? 4.8f : 3.6f, normImg);
        img.GenerateMipmaps();
        normImg.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            NormalEnabled = true,
            NormalTexture = ImageTexture.CreateFromImage(normImg),
            NormalScale = ribbedCuff ? 0.80f : 0.62f,
            Roughness = ribbedCuff ? 0.88f : 0.78f,
            Metallic = 0.03f,
            Uv1Scale = ribbedCuff ? new Vector3(1.5f, 1.0f, 1.0f) : new Vector3(2.0f, 2.0f, 1.0f)
        };
    }

    public static StandardMaterial3D CreateNomexGloveMaterial(Color baseColor)
    {
        return CreateNomexFabricMaterial(baseColor, false, null, false);
    }

