    public static StandardMaterial3D CreateTireSidewallMaterial(Color compoundColor)
    {
        const int sz = 512;
        var img = Image.CreateEmpty(sz, sz, false, Image.Format.Rgba8);
        float half = sz * 0.5f;
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float dx = (x - half) / half;
                float dy = (y - half) / half;
                float r = Mathf.Sqrt(dx * dx + dy * dy);
                float ang = Mathf.Atan2(dy, dx);
                if (ang < 0f) ang += Mathf.Tau;

                Color col = new Color(0.075f, 0.085f, 0.105f);
                if (r > 0.72f && r < 0.81f)
                {
                    bool inMainArc = (ang > 0.24f && ang < 1.88f) || (ang > 3.38f && ang < 5.02f);
                    bool inWhiteTick = (ang > 2.22f && ang < 2.98f) || (ang > 5.36f && ang < 6.12f);
                    if (inMainArc) col = compoundColor;
                    else if (inWhiteTick) col = new Color(0.95f, 0.96f, 0.99f);
                }
                else if (r > 0.62f && r <= 0.65f)
                {
                    // Subtle inner sidewall moulding ring
                    col = new Color(0.13f, 0.15f, 0.18f);
                }
                else if (r <= 0.60f && r > 0.545f)
                {
                    // Brushed machined alloy rim lip
                    float glint = 0.46f + 0.16f * Mathf.Sin(ang * 2f);
                    col = new Color(glint, glint * 1.04f, glint * 1.12f);
                }
                else if (r <= 0.545f && r > 0.15f)
                {
                    // High-res 10-spoke aero carbon wheel cover with cooling louvers
                    float spoke = Mathf.Abs(Mathf.Sin(ang * 5.0f));
                    float v = spoke < 0.11f ? 0.24f : (spoke < 0.22f ? 0.14f : 0.08f);
                    col = new Color(v, v * 1.05f, v * 1.15f);
                }
                else if (r <= 0.15f)
                {
                    // Anodized F1 center lock-nut
                    col = r < 0.075f ? new Color(0.88f, 0.92f, 0.98f) : new Color(0.88f, 0.11f, 0.13f);
                }

                img.SetPixel(x, y, col);
            }
        }
        img.GenerateMipmaps();
        return new StandardMaterial3D
        {
            AlbedoTexture = ImageTexture.CreateFromImage(img),
            Roughness = 0.38f,
            Metallic = 0.22f
        };
    }

    public static StandardMaterial3D CreateMetalMaterial(Color tint, float roughness = 0.22f)
    {
        return new StandardMaterial3D
        {
            AlbedoColor = tint,
            Metallic = 0.90f,
            Roughness = roughness
        };
    }

    public static StandardMaterial3D CreateEmissiveMaterial(Color color, float energy = 1.6f)
    {
        return new StandardMaterial3D
        {
            AlbedoColor = color,
            EmissionEnabled = true,
            Emission = color,
            EmissionEnergyMultiplier = energy,
            Roughness = 0.18f
        };
    }

    public static StandardMaterial3D CreateVertexColorMaterial(float roughness = 0.78f, bool doubleSided = false)
    {
        return new StandardMaterial3D
        {
            VertexColorUseAsAlbedo = true,
            Roughness = roughness,
            Metallic = 0.05f,
            CullMode = doubleSided ? BaseMaterial3D.CullModeEnum.Disabled : BaseMaterial3D.CullModeEnum.Back
        };
    }

    private static void GenerateNormalMapFromHeight(float[,] hMap, int sz, float strength, Image outImg)
    {
        for (int y = 0; y < sz; y++)
        {
            for (int x = 0; x < sz; x++)
            {
                float dx = (hMap[(x + 1) % sz, y] - hMap[(x - 1 + sz) % sz, y]) * strength;
                float dy = (hMap[x, (y + 1) % sz] - hMap[x, (y - 1 + sz) % sz]) * strength;
                Vector3 n = new Vector3(-dx, -dy, 1.0f).Normalized();
                outImg.SetPixel(x, y, new Color(n.X * 0.5f + 0.5f, n.Y * 0.5f + 0.5f, n.Z * 0.5f + 0.5f));
            }
        }
    }
}

