using Godot;
using System;
using System.Collections.Generic;

namespace ApexGP24;

public struct TrackSample
{
    public Vector3 Center;
    public Vector3 Forward;
    public Vector3 Right;
    public float Distance;
    public float Curvature;
}

public partial class TrackBuilder3D : Node3D
{
    public const float TrackHalfWidth = 7.2f;
    public const float KerbWidth = 0.95f;
    public const float RunoffWidth = 7.8f;
    public const float BarrierOffset = TrackHalfWidth + KerbWidth + RunoffWidth;

    public List<TrackSample> Samples { get; } = new();
    public float TotalLength { get; private set; } = 1.0f;

    private readonly List<(Node3D node, float phase)> _wavingFlags = new();
    private readonly List<OmniLight3D> _floodLights = new();
    private StandardMaterial3D _floodLampMat;
    private MeshInstance3D _racingLineMesh;
    private float _windTime = 0f;

    public void BuildCircuit()
    {
        GenerateSplineSamples();
        BuildGroundPlane();
        BuildTrackMeshes();
        BuildStartGantry();
        BuildRacingLineAndBrakingBoards();
        BuildGrandstandsTentsAndScenery();
        BuildHorizonMountainsAndClouds();
    }

    public void SetRacingLineVisible(bool visible)
    {
        if (_racingLineMesh != null) _racingLineMesh.Visible = visible;
    }

    public void SetNightMode(bool isNight)
    {
        if (_floodLampMat != null)
        {
            _floodLampMat.EmissionEnabled = isNight;
            _floodLampMat.EmissionEnergyMultiplier = isNight ? 4.5f : 0.0f;
            _floodLampMat.AlbedoColor = isNight ? new Color(0.95f, 0.98f, 1.0f) : new Color(0.65f, 0.70f, 0.76f);
        }
        foreach (OmniLight3D l in _floodLights)
        {
            l.Visible = isNight;
        }
    }

    public override void _Process(double delta)
    {
        _windTime += (float)delta;
        for (int i = 0; i < _wavingFlags.Count; i++)
        {
            var item = _wavingFlags[i];
            float sway = Mathf.Sin(_windTime * 4.6f + item.phase) * 14.0f;
            item.node.RotationDegrees = new Vector3(0f, sway, Mathf.Cos(_windTime * 3.1f + item.phase) * 4.0f);
        }
    }

    private void GenerateSplineSamples()
    {
        Vector3[] controlPts =
        {
            new Vector3(0f, 0.0f, 0f),
            new Vector3(0f, 0.2f, -150f),
            new Vector3(12f, 1.8f, -280f),
            new Vector3(72f, 3.6f, -335f),
            new Vector3(145f, 4.2f, -310f),
            new Vector3(188f, 2.4f, -225f),
            new Vector3(165f, 1.0f, -135f),
            new Vector3(230f, 2.5f, -55f),
            new Vector3(268f, 3.8f, 55f),
            new Vector3(235f, 2.6f, 170f),
            new Vector3(140f, 1.2f, 225f),
            new Vector3(45f, 0.6f, 200f),
            new Vector3(2f, 0.0f, 118f)
        };

        var rawPts = new List<Vector3>();
        int n = controlPts.Length;
        const int subDiv = 28;

        for (int i = 0; i < n; i++)
        {
            Vector3 p0 = controlPts[(i - 1 + n) % n];
            Vector3 p1 = controlPts[i];
            Vector3 p2 = controlPts[(i + 1) % n];
            Vector3 p3 = controlPts[(i + 2) % n];

            for (int s = 0; s < subDiv; s++)
            {
                float t = s / (float)subDiv;
                rawPts.Add(CatmullRom(p0, p1, p2, p3, t));
            }
        }

        Samples.Clear();
        float accDist = 0f;
        int count = rawPts.Count;

        for (int i = 0; i < count; i++)
        {
            Vector3 prev = rawPts[(i - 1 + count) % count];
            Vector3 curr = rawPts[i];
            Vector3 next = rawPts[(i + 1) % count];

            if (i > 0) accDist += curr.DistanceTo(prev);

            Vector3 fwd = (next - prev).Normalized();
            Vector3 right = fwd.Cross(Vector3.Up).Normalized();
            Vector3 v1 = (curr - prev).Normalized();
            Vector3 v2 = (next - curr).Normalized();
            float crossY = v1.X * v2.Z - v1.Z * v2.X;
            float segLen = Mathf.Max(0.1f, curr.DistanceTo(prev));

            Samples.Add(new TrackSample
            {
                Center = curr,
                Forward = fwd,
                Right = right,
                Distance = accDist,
                Curvature = crossY / segLen
            });
        }

        TotalLength = accDist + rawPts[0].DistanceTo(rawPts[count - 1]);
    }

    private static Vector3 CatmullRom(Vector3 p0, Vector3 p1, Vector3 p2, Vector3 p3, float t)
    {
        float t2 = t * t;
        float t3 = t2 * t;
        return 0.5f * (
            (2.0f * p1) +
            (-p0 + p2) * t +
            (2.0f * p0 - 5.0f * p1 + 4.0f * p2 - p3) * t2 +
            (-p0 + 3.0f * p1 - 3.0f * p2 + p3) * t3
        );
    }

    public TrackSample SampleAtDistance(float dist)
    {
        float wrapped = ((dist % TotalLength) + TotalLength) % TotalLength;
        int count = Samples.Count;
        int lo = 0;
        int hi = count - 1;
        while (lo + 1 < hi)
        {
            int mid = (lo + hi) >> 1;
            if (Samples[mid].Distance <= wrapped) lo = mid;
            else hi = mid;
        }

        int i0 = lo;
        int i1 = (lo + 1) % count;
        float d0 = Samples[i0].Distance;
        float d1 = i1 == 0 ? TotalLength : Samples[i1].Distance;
        float span = Mathf.Max(0.001f, d1 - d0);
        float frac = Mathf.Clamp((wrapped - d0) / span, 0f, 1f);

        TrackSample a = Samples[i0];
        TrackSample b = Samples[i1];
        Vector3 fwd = a.Forward.Lerp(b.Forward, frac).Normalized();
        return new TrackSample
        {
            Center = a.Center.Lerp(b.Center, frac),
            Forward = fwd,
            Right = fwd.Cross(Vector3.Up).Normalized(),
            Distance = wrapped,
            Curvature = Mathf.Lerp(a.Curvature, b.Curvature, frac)
        };
    }

    private void BuildGroundPlane()
    {
        AddChild(new MeshInstance3D
        {
            Mesh = new PlaneMesh { Size = new Vector2(1800f, 1800f) },
            Position = new Vector3(110f, -0.35f, -50f),
            MaterialOverride = ProceduralMaterialFactory.CreateGrassMaterial()
        });
    }

    private void BuildTrackMeshes()
    {
        var roadSt = new SurfaceTool();
        roadSt.Begin(Mesh.PrimitiveType.Triangles);

        var kerbSt = new SurfaceTool();
        kerbSt.Begin(Mesh.PrimitiveType.Triangles);

        var gravelSt = new SurfaceTool();
        gravelSt.Begin(Mesh.PrimitiveType.Triangles);

        var wallSt = new SurfaceTool();
        wallSt.Begin(Mesh.PrimitiveType.Triangles);

        int count = Samples.Count;
        for (int i = 0; i < count; i++)
        {
            TrackSample a = Samples[i];
            TrackSample b = Samples[(i + 1) % count];
            float dA = a.Distance;
            float dB = i == count - 1 ? TotalLength : b.Distance;
            float vA = dA * 0.10f;
            float vB = dB * 0.10f;

            // 1. Main Asphalt Surface (CW from +Y -> Upward normals & shadows!)
            Vector3 rLA = a.Center - a.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            Vector3 rRA = a.Center + a.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            Vector3 rLB = b.Center - b.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            Vector3 rRB = b.Center + b.Right * TrackHalfWidth + Vector3.Up * 0.04f;
            AddUvQuad(roadSt, rLA, rLB, rRB, rRA, new Vector2(0, vA), new Vector2(0, vB), new Vector2(1, vB), new Vector2(1, vA));

            // 2. Red & White FIA Kerbs + Corner Gravel Traps + Grass Verges + Sponsor Walls!
            bool alt = ((int)(dA / 3.6f) % 2) == 0;
            Color kerbCol = alt ? new Color(0.88f, 0.10f, 0.10f) : new Color(0.96f, 0.97f, 0.99f);
            Color vergeCol = alt ? new Color(0.16f, 0.36f, 0.15f) : new Color(0.13f, 0.32f, 0.13f);
            float curv = a.Curvature;

            foreach (float side in new[] { -1f, 1f })
            {
                Vector3 kInA = a.Center + a.Right * (side * TrackHalfWidth) + Vector3.Up * 0.05f;
                Vector3 kOutA = a.Center + a.Right * (side * (TrackHalfWidth + KerbWidth)) + Vector3.Up * 0.10f;
                Vector3 kInB = b.Center + b.Right * (side * TrackHalfWidth) + Vector3.Up * 0.05f;
                Vector3 kOutB = b.Center + b.Right * (side * (TrackHalfWidth + KerbWidth)) + Vector3.Up * 0.10f;

                Vector3 runOutA = a.Center + a.Right * (side * BarrierOffset) + Vector3.Up * 0.02f;
                Vector3 runOutB = b.Center + b.Right * (side * BarrierOffset) + Vector3.Up * 0.02f;

                Vector3 wBotA = runOutA;
                Vector3 wTopA = runOutA + Vector3.Up * 1.18f;
                Vector3 wBotB = runOutB;
                Vector3 wTopB = runOutB + Vector3.Up * 1.18f;

                // Outside of corners gets authentic raked FIA Gravel Traps!
                bool isGravel = (side < 0 && curv > 0.0045f) || (side > 0 && curv < -0.0045f);
                float wuA = dA * 0.032f;
                float wuB = dB * 0.032f;

                if (side < 0)
                {
                    AddColorQuad(kerbSt, kOutA, kOutB, kInB, kInA, kerbCol);
                    if (isGravel)
                    {
                        AddUvQuad(gravelSt, runOutA, runOutB, kOutB, kOutA, new Vector2(0, vA * 0.6f), new Vector2(0, vB * 0.6f), new Vector2(1.2f, vB * 0.6f), new Vector2(1.2f, vA * 0.6f));
                    }
                    else
                    {
                        AddColorQuad(kerbSt, runOutA, runOutB, kOutB, kOutA, vergeCol);
                    }
                    AddUvQuad(wallSt, wBotA, wBotB, wTopB, wTopA, new Vector2(wuA, 1), new Vector2(wuB, 1), new Vector2(wuB, 0), new Vector2(wuA, 0));
                }
                else
                {
                    AddColorQuad(kerbSt, kInA, kInB, kOutB, kOutA, kerbCol);
                    if (isGravel)
                    {
                        AddUvQuad(gravelSt, kOutA, kOutB, runOutB, runOutA, new Vector2(0, vA * 0.6f), new Vector2(0, vB * 0.6f), new Vector2(1.2f, vB * 0.6f), new Vector2(1.2f, vA * 0.6f));
                    }
                    else
                    {
                        AddColorQuad(kerbSt, kOutA, kOutB, runOutB, runOutA, vergeCol);
                    }
                    AddUvQuad(wallSt, wBotB, wBotA, wTopA, wTopB, new Vector2(wuB, 1), new Vector2(wuA, 1), new Vector2(wuA, 0), new Vector2(wuB, 0));
                }
            }
        }

        roadSt.GenerateNormals();
        roadSt.GenerateTangents();
        AddChild(new MeshInstance3D
        {
            Mesh = roadSt.Commit(),
            MaterialOverride = ProceduralMaterialFactory.CreateAsphaltMaterial()
        });

        kerbSt.GenerateNormals();
        AddChild(new MeshInstance3D
        {
            Mesh = kerbSt.Commit(),
            MaterialOverride = ProceduralMaterialFactory.CreateVertexColorMaterial(0.78f, true)
        });

        gravelSt.GenerateNormals();
        gravelSt.GenerateTangents();
        AddChild(new MeshInstance3D
        {
            Mesh = gravelSt.Commit(),
            MaterialOverride = ProceduralMaterialFactory.CreateGravelMaterial()
        });

        wallSt.GenerateNormals();
        AddChild(new MeshInstance3D
        {
            Mesh = wallSt.Commit(),
            MaterialOverride = ProceduralMaterialFactory.CreateBarrierSponsorMaterial()
        });
    }

    private void BuildStartGantry()
    {
        TrackSample s0 = SampleAtDistance(0f);
        var gantry = new Node3D
        {
            Position = s0.Center,
            Basis = Basis.LookingAt(s0.Forward, Vector3.Up)
        };
        AddChild(gantry);

        var darkMetal = ProceduralMaterialFactory.CreateMetalMaterial(new Color(0.14f, 0.17f, 0.22f), 0.35f);
        var bannerMat = new StandardMaterial3D { AlbedoColor = new Color(0.86f, 0.06f, 0.07f), Roughness = 0.32f };

        foreach (float side in new[] { -1f, 1f })
        {
            gantry.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(0.75f, 7.6f, 0.75f) },
                Position = new Vector3(side * (TrackHalfWidth + 1.9f), 3.8f, 0f),
                MaterialOverride = darkMetal
            });
        }

        gantry.AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3((TrackHalfWidth + 2.3f) * 2f, 1.55f, 0.95f) },
            Position = new Vector3(0f, 7.0f, 0f),
            MaterialOverride = bannerMat
        });

        gantry.AddChild(new Label3D
        {
            Text = "APEX GP 24  •  PIRELLI  •  START",
            Position = new Vector3(0f, 7.0f, 0.52f),
            FontSize = 68,
            PixelSize = 0.0082f,
            Modulate = Colors.White
        });

        // FIA 5-Pod Start Light Rack hanging under gantry
        for (int p = -2; p <= 2; p++)
        {
            gantry.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(0.55f, 0.95f, 0.35f) },
                Position = new Vector3(p * 1.45f, 5.75f, 0.15f),
                MaterialOverride = darkMetal
            });
        }

        // Checkered Start / Finish Strip
        for (int c = -6; c <= 6; c++)
        {
            for (int r = 0; r < 2; r++)
            {
                bool white = ((c + r) & 1) == 0;
                gantry.AddChild(new MeshInstance3D
                {
                    Mesh = new BoxMesh { Size = new Vector3(1.05f, 0.015f, 0.65f) },
                    Position = new Vector3(c * 1.05f, 0.052f, (r - 0.5f) * 0.65f),
                    MaterialOverride = new StandardMaterial3D { AlbedoColor = white ? Colors.White : new Color(0.08f, 0.09f, 0.11f), Roughness = 0.65f }
                });
            }
        }
    }

    private void BuildGrandstandsTentsAndScenery()
    {
        var concreteMat = new StandardMaterial3D { AlbedoColor = new Color(0.24f, 0.27f, 0.33f), Roughness = 0.86f };
        var roofMat = new StandardMaterial3D { AlbedoColor = new Color(0.94f, 0.96f, 0.99f), Roughness = 0.42f };
        var crowdMat = ProceduralMaterialFactory.CreateCrowdMaterial();
        var redTrimMat = new StandardMaterial3D { AlbedoColor = new Color(0.86f, 0.09f, 0.09f), Roughness = 0.40f };
        var poleMat = ProceduralMaterialFactory.CreateMetalMaterial(new Color(0.80f, 0.84f, 0.90f), 0.30f);
        var trunkMat = new StandardMaterial3D { AlbedoColor = new Color(0.29f, 0.19f, 0.11f), Roughness = 0.95f };
        var leafDarkMat = new StandardMaterial3D { AlbedoColor = new Color(0.11f, 0.32f, 0.13f), Roughness = 0.88f };
        var leafLightMat = new StandardMaterial3D { AlbedoColor = new Color(0.18f, 0.45f, 0.17f), Roughness = 0.86f };
        var tentWallMat = new StandardMaterial3D { AlbedoColor = new Color(0.92f, 0.94f, 0.97f), Roughness = 0.65f };
        var tentRoofMat = new StandardMaterial3D { AlbedoColor = new Color(0.98f, 0.99f, 1.00f), Roughness = 0.50f };
        _floodLampMat = new StandardMaterial3D { AlbedoColor = new Color(0.75f, 0.80f, 0.86f), Emission = new Color(0.88f, 0.95f, 1.0f), EmissionEnabled = false };

        Color[][] flagPalettes =
        {
            new[] { new Color(0.86f, 0.10f, 0.10f), new Color(1.00f, 0.82f, 0.08f), new Color(0.86f, 0.10f, 0.10f) }, // Spain
            new[] { new Color(0.02f, 0.58f, 0.28f), new Color(0.96f, 0.97f, 0.99f), new Color(0.84f, 0.14f, 0.18f) }, // Italy
            new[] { new Color(1.00f, 0.46f, 0.02f), new Color(1.00f, 0.56f, 0.08f), new Color(1.00f, 0.46f, 0.02f) }, // Orange Army
            new[] { new Color(0.05f, 0.34f, 0.90f), new Color(0.96f, 0.97f, 0.99f), new Color(0.88f, 0.09f, 0.12f) }  // Alpine / UK
        };

        // 1. Packed Tiered 3D F1 Grandstands with Animated Waving National Flags!
        int gsIdx = 0;
        for (float d = 18f; d < TotalLength - 35f; d += 78f)
        {
            TrackSample s = SampleAtDistance(d);
            float side = (gsIdx % 2 == 0) ? -1f : 1f;
            gsIdx++;

            var stand = new Node3D
            {
                Position = s.Center + s.Right * (side * (BarrierOffset + 9.2f)),
                Basis = Basis.LookingAt(s.Forward, Vector3.Up)
            };
            AddChild(stand);

            // Concrete front wall & red FIA fascia
            stand.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(1.2f, 2.2f, 38.0f) },
                Position = new Vector3(-side * 4.8f, 1.1f, 0f),
                MaterialOverride = concreteMat
            });
            stand.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(1.3f, 0.55f, 38.0f) },
                Position = new Vector3(-side * 4.8f, 2.2f, 0f),
                MaterialOverride = redTrimMat
            });

            // Sloped tiered seating deck covered in vibrant packed F1 crowd texture!
            stand.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(10.5f, 0.8f, 37.5f) },
                Position = new Vector3(0f, 4.4f, 0f),
                RotationDegrees = new Vector3(0f, 0f, side * 26f),
                MaterialOverride = crowdMat
            });
            // Rear grandstand wall & white cantilever roof
            stand.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(1.0f, 7.6f, 38.0f) },
                Position = new Vector3(side * 4.8f, 3.8f, 0f),
                MaterialOverride = concreteMat
            });
            stand.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(12.2f, 0.42f, 39.0f) },
                Position = new Vector3(-side * 0.4f, 8.2f, 0f),
                RotationDegrees = new Vector3(0f, 0f, side * 5f),
                MaterialOverride = roofMat
            });
            for (int col = -2; col <= 2; col++)
            {
                stand.AddChild(new MeshInstance3D
                {
                    Mesh = new BoxMesh { Size = new Vector3(0.28f, 0.34f, 0.28f) },
                    Position = new Vector3(side * 4.4f, 7.6f, col * 8.5f),
                    MaterialOverride = poleMat
                });
                stand.AddChild(new MeshInstance3D
                {
                    Mesh = new BoxMesh { Size = new Vector3(11.2f, 0.18f, 0.22f) },
                    Position = new Vector3(-side * 0.3f, 7.92f, col * 8.5f),
                    RotationDegrees = new Vector3(0f, 0f, side * 5f),
                    MaterialOverride = poleMat
                });
            }

            // 5 Animated Waving National / Fan Flags along the upper grandstand deck
            for (int f = 0; f < 5; f++)
            {
                float fz = -14.0f + f * 7.0f;
                float fx = side * (-1.5f + (f % 2) * 2.2f);
                float fy = 4.2f + (f % 2) * 1.1f;

                stand.AddChild(new MeshInstance3D
                {
                    Mesh = new CylinderMesh { TopRadius = 0.03f, BottomRadius = 0.04f, Height = 3.2f, RadialSegments = 6 },
                    Position = new Vector3(fx, fy + 1.6f, fz),
                    MaterialOverride = poleMat
                });

                var flagPivot = new Node3D { Position = new Vector3(fx, fy + 2.85f, fz) };
                stand.AddChild(flagPivot);
                Color[] pal = flagPalettes[(gsIdx + f) % flagPalettes.Length];
                for (int st = 0; st < 3; st++)
                {
                    flagPivot.AddChild(new MeshInstance3D
                    {
                        Mesh = new BoxMesh { Size = new Vector3(1.65f, 0.34f, 0.04f) },
                        Position = new Vector3(-side * 0.85f, 0.34f - st * 0.34f, 0f),
                        MaterialOverride = new StandardMaterial3D { AlbedoColor = pal[st], Roughness = 0.72f }
                    });
                }
                _wavingFlags.Add((flagPivot, gsIdx * 1.7f + f * 0.9f));
            }
        }

        // 2. White Peaked-Roof Paddock / Hospitality Pavilions (inspired by left side of reference photo!)
        for (float d = 48f; d < TotalLength - 40f; d += 145f)
        {
            TrackSample s = SampleAtDistance(d);
            float side = ((int)(d / 145f) % 2 == 0) ? 1f : -1f;
            var tent = new Node3D
            {
                Position = s.Center + s.Right * (side * (BarrierOffset + 8.0f)),
                Basis = Basis.LookingAt(s.Forward, Vector3.Up)
            };
            AddChild(tent);

            tent.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(6.8f, 3.0f, 8.5f) },
                Position = new Vector3(0f, 1.5f, 0f),
                MaterialOverride = tentWallMat
            });
            // Peaked pyramidal white canopy roof (4-sided cone)
            tent.AddChild(new MeshInstance3D
            {
                Mesh = new CylinderMesh { TopRadius = 0.05f, BottomRadius = 5.4f, Height = 2.8f, RadialSegments = 4 },
                Position = new Vector3(0f, 4.4f, 0f),
                RotationDegrees = new Vector3(0f, 45f, 0f),
                MaterialOverride = tentRoofMat
            });
            tent.AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(7.1f, 0.28f, 8.8f) },
                Position = new Vector3(0f, 3.05f, 0f),
                MaterialOverride = redTrimMat
            });
        }

        // 3. Multi-Layered Trackside Trees + Night Stadium Floodlight Towers!
        int lightIdx = 0;
        for (float d = 12f; d < TotalLength; d += 32f)
        {
            TrackSample s = SampleAtDistance(d);
            var leafMidMat = new StandardMaterial3D { AlbedoColor = new Color(0.14f, 0.39f, 0.14f), Roughness = 0.87f };
            foreach (float side in new[] { -1f, 1f })
            {
                float jitter = ((d * 0.37f) % 11f);
                float treeScale = 0.88f + ((d * 0.13f) % 0.42f);
                Vector3 treePos = s.Center + s.Right * (side * (BarrierOffset + 19.5f + jitter));
                var tree = new Node3D { Position = treePos, Scale = new Vector3(treeScale, treeScale, treeScale) };
                AddChild(tree);

                // Tapered natural bark trunk + 4 organic overlapping foliage crown clusters (zero toy cone look!)
                tree.AddChild(new MeshInstance3D
                {
                    Mesh = new CylinderMesh { TopRadius = 0.22f, BottomRadius = 0.42f, Height = 4.0f, RadialSegments = 10 },
                    Position = new Vector3(0f, 2.0f, 0f),
                    MaterialOverride = trunkMat
                });
                tree.AddChild(new MeshInstance3D
                {
                    Mesh = new SphereMesh { Radius = 3.0f, Height = 4.4f, RadialSegments = 14, Rings = 8 },
                    Position = new Vector3(-0.7f * side, 4.8f, -0.5f),
                    MaterialOverride = leafDarkMat
                });
                tree.AddChild(new MeshInstance3D
                {
                    Mesh = new SphereMesh { Radius = 2.7f, Height = 4.0f, RadialSegments = 14, Rings = 8 },
                    Position = new Vector3(1.1f * side, 5.1f, 0.7f),
                    MaterialOverride = leafMidMat
                });
                tree.AddChild(new MeshInstance3D
                {
                    Mesh = new SphereMesh { Radius = 2.4f, Height = 3.6f, RadialSegments = 14, Rings = 8 },
                    Position = new Vector3(-0.2f * side, 6.8f, 0.2f),
                    MaterialOverride = leafLightMat
                });
                tree.AddChild(new MeshInstance3D
                {
                    Mesh = new SphereMesh { Radius = 2.0f, Height = 3.2f, RadialSegments = 12, Rings = 6 },
                    Position = new Vector3(0.5f * side, 4.4f, -1.2f),
                    MaterialOverride = leafDarkMat
                });
            }

            // Stadium Floodlight Tower every 64m (alternating sides)
            if ((lightIdx % 2) == 0)
            {
                float fSide = ((lightIdx / 2) % 2 == 0) ? -1f : 1f;
                var tower = new Node3D
                {
                    Position = s.Center + s.Right * (fSide * (BarrierOffset + 1.8f)),
                    Basis = Basis.LookingAt(s.Forward, Vector3.Up)
                };
                AddChild(tower);

                tower.AddChild(new MeshInstance3D
                {
                    Mesh = new CylinderMesh { TopRadius = 0.16f, BottomRadius = 0.26f, Height = 13.5f, RadialSegments = 8 },
                    Position = new Vector3(0f, 6.75f, 0f),
                    MaterialOverride = poleMat
                });
                tower.AddChild(new MeshInstance3D
                {
                    Mesh = new BoxMesh { Size = new Vector3(2.8f, 1.1f, 0.45f) },
                    Position = new Vector3(-fSide * 1.1f, 13.4f, 0f),
                    RotationDegrees = new Vector3(0f, 0f, fSide * 24f),
                    MaterialOverride = _floodLampMat
                });

                var light = new OmniLight3D
                {
                    Position = new Vector3(-fSide * 3.0f, 11.5f, 0f),
                    LightColor = new Color(0.90f, 0.95f, 1.0f),
                    LightEnergy = 8.5f,
                    OmniRange = 46f,
                    OmniAttenuation = 1.4f,
                    Visible = false
                };
                tower.AddChild(light);
                _floodLights.Add(light);
            }
            lightIdx++;
        }
    }


    private void BuildRacingLineAndBrakingBoards()
    {
        // 1. Dynamic 3D FIA Racing Line Ribbon (Green = Full Throttle, Yellow = Apex/Lift, Red = Brake!)
        var lineSt = new SurfaceTool();
        lineSt.Begin(Mesh.PrimitiveType.Triangles);

        int count = Samples.Count;
        float[] targetSpeed = new float[count];
        for (int i = 0; i < count; i++)
        {
            float absK = Mathf.Abs(Samples[i].Curvature);
            targetSpeed[i] = absK < 0.004f ? 340f : Mathf.Clamp(Mathf.Sqrt(78f / absK) * 3.6f, 95f, 340f);
        }
        // Backward braking envelope (~95m braking zone)
        for (int pass = 0; pass < 2; pass++)
        {
            for (int i = count - 1; i >= 0; i--)
            {
                int next = (i + 1) % count;
                float ds = Mathf.Max(0.5f, Samples[next].Center.DistanceTo(Samples[i].Center));
                float vNext = targetSpeed[next] / 3.6f;
                float vAllow = Mathf.Sqrt(vNext * vNext + 2f * 32f * ds) * 3.6f;
                if (vAllow < targetSpeed[i]) targetSpeed[i] = vAllow;
            }
        }

        for (int i = 0; i < count; i++)
        {
            TrackSample a = Samples[i];
            TrackSample b = Samples[(i + 1) % count];
            float kA = a.Curvature;
            float kB = b.Curvature;

            // Out-In-Out FIA racing line offset
            float offA = Mathf.Clamp(kA * 180f, -TrackHalfWidth * 0.62f, TrackHalfWidth * 0.62f);
            float offB = Mathf.Clamp(kB * 180f, -TrackHalfWidth * 0.62f, TrackHalfWidth * 0.62f);

            float spd = targetSpeed[i];
            float spdNext = targetSpeed[(i + 5) % count];
            Color col = (spd - spdNext > 18f || spd < 155f)
                ? new Color(1.0f, 0.14f, 0.10f, 0.78f)
                : (spd < 235f ? new Color(1.0f, 0.82f, 0.08f, 0.72f) : new Color(0.05f, 0.92f, 0.42f, 0.56f));

            const float halfRibbon = 0.24f;
            Vector3 cA = a.Center + a.Right * offA + Vector3.Up * 0.068f;
            Vector3 cB = b.Center + b.Right * offB + Vector3.Up * 0.068f;
            AddColorQuad(
                lineSt,
                cA - a.Right * halfRibbon,
                cB - b.Right * halfRibbon,
                cB + b.Right * halfRibbon,
                cA + a.Right * halfRibbon,
                col);
        }

        lineSt.GenerateNormals();
        var lineMat = new StandardMaterial3D
        {
            VertexColorUseAsAlbedo = true,
            Transparency = BaseMaterial3D.TransparencyEnum.Alpha,
            ShadingMode = BaseMaterial3D.ShadingModeEnum.Unshaded,
            CullMode = BaseMaterial3D.CullModeEnum.Disabled
        };
        _racingLineMesh = new MeshInstance3D
        {
            Name = "RacingLine3D",
            Mesh = lineSt.Commit(),
            MaterialOverride = lineMat
        };
        AddChild(_racingLineMesh);

        // 2. Authentic FIA 150m / 100m / 50m Braking Marker Boards before heavy corners!
        var boardBg = new StandardMaterial3D { AlbedoColor = new Color(0.96f, 0.97f, 0.99f), Roughness = 0.4f };
        var postMat = ProceduralMaterialFactory.CreateMetalMaterial(new Color(0.20f, 0.24f, 0.30f), 0.4f);
        float lastCornerDist = -200f;

        for (int i = 0; i < count; i++)
        {
            float absK = Mathf.Abs(Samples[i].Curvature);
            if (absK > 0.018f && (Samples[i].Distance - lastCornerDist) > 220f)
            {
                lastCornerDist = Samples[i].Distance;
                float outsideSide = Samples[i].Curvature > 0f ? -1f : 1f;
                int[] markers = { 150, 100, 50 };
                foreach (int m in markers)
                {
                    TrackSample ms = SampleAtDistance(Samples[i].Distance - m);
                    var board = new Node3D
                    {
                        Position = ms.Center + ms.Right * (outsideSide * (TrackHalfWidth + 2.4f)),
                        Basis = Basis.LookingAt(ms.Forward, Vector3.Up)
                    };
                    AddChild(board);

                    board.AddChild(new MeshInstance3D
                    {
                        Mesh = new BoxMesh { Size = new Vector3(0.08f, 1.3f, 0.08f) },
                        Position = new Vector3(0f, 0.65f, 0f),
                        MaterialOverride = postMat
                    });
                    board.AddChild(new MeshInstance3D
                    {
                        Mesh = new BoxMesh { Size = new Vector3(1.15f, 0.65f, 0.08f) },
                        Position = new Vector3(0f, 1.25f, 0f),
                        MaterialOverride = boardBg
                    });
                    board.AddChild(new Label3D
                    {
                        Text = $"{m}",
                        Position = new Vector3(0f, 1.25f, 0.06f),
                        FontSize = 64,
                        PixelSize = 0.0065f,
                        Modulate = new Color(0.06f, 0.08f, 0.12f),
                        OutlineSize = 0
                    });
                }
            }
        }
    }

    private void BuildHorizonMountainsAndClouds()
    {
        // Scenic distant mountain ridge ring around the circuit (adds huge depth & realism!)
        var rng = new Random(909);
        var mtnFarMat = new StandardMaterial3D { AlbedoColor = new Color(0.24f, 0.34f, 0.44f), Roughness = 0.96f };
        var mtnNearMat = new StandardMaterial3D { AlbedoColor = new Color(0.16f, 0.28f, 0.21f), Roughness = 0.94f };
        Vector3 circuitCenter = new Vector3(115f, -2f, -45f);

        // Soft wide rolling hills & distant ridges (natural European GP silhouette instead of sharp cones!)
        for (int i = 0; i < 32; i++)
        {
            float ang = (i / 32f) * Mathf.Tau;
            float dist = 560f + (float)rng.NextDouble() * 140f;
            float h = 34f + (float)rng.NextDouble() * 44f;
            float rx = 125f + (float)rng.NextDouble() * 95f;
            float rz = 90f + (float)rng.NextDouble() * 70f;
            AddChild(new MeshInstance3D
            {
                Mesh = new SphereMesh { Radius = 1.0f, Height = 2.0f, RadialSegments = 14, Rings = 7 },
                Position = circuitCenter + new Vector3(Mathf.Cos(ang) * dist, -8f, Mathf.Sin(ang) * dist),
                Scale = new Vector3(rx, h, rz),
                RotationDegrees = new Vector3(0f, Mathf.RadToDeg(ang), 0f),
                MaterialOverride = (i % 2 == 0) ? mtnFarMat : mtnNearMat
            });
        }

        // Soft volumetric cloud puffs drifting high above the horizon
        var cloudMat = new StandardMaterial3D
        {
            AlbedoColor = new Color(0.96f, 0.98f, 1.0f, 0.72f),
            Transparency = BaseMaterial3D.TransparencyEnum.Alpha,
            Roughness = 1.0f
        };
        for (int c = 0; c < 18; c++)
        {
            float ang = (c / 18f) * Mathf.Tau + 0.12f;
            float dist = 420f + (float)rng.NextDouble() * 220f;
            float cy = 115f + (float)rng.NextDouble() * 55f;
            AddChild(new MeshInstance3D
            {
                Mesh = new SphereMesh { Radius = 28f + (float)rng.NextDouble() * 22f, Height = 16f, RadialSegments = 10, Rings = 5 },
                Position = circuitCenter + new Vector3(Mathf.Cos(ang) * dist, cy, Mathf.Sin(ang) * dist),
                Scale = new Vector3(2.4f, 0.55f, 1.2f),
                MaterialOverride = cloudMat
            });
        }
    }

    private static void AddUvQuad(SurfaceTool st, Vector3 a, Vector3 b, Vector3 c, Vector3 d, Vector2 uvA, Vector2 uvB, Vector2 uvC, Vector2 uvD)
    {
        st.SetUV(uvA); st.AddVertex(a);
        st.SetUV(uvB); st.AddVertex(b);
        st.SetUV(uvC); st.AddVertex(c);

        st.SetUV(uvA); st.AddVertex(a);
        st.SetUV(uvC); st.AddVertex(c);
        st.SetUV(uvD); st.AddVertex(d);
    }

    private static void AddColorQuad(SurfaceTool st, Vector3 a, Vector3 b, Vector3 c, Vector3 d, Color col)
    {
        st.SetColor(col); st.AddVertex(a);
        st.SetColor(col); st.AddVertex(b);
        st.SetColor(col); st.AddVertex(c);

        st.SetColor(col); st.AddVertex(a);
        st.SetColor(col); st.AddVertex(c);
        st.SetColor(col); st.AddVertex(d);
    }
}

