using Godot;
using System;
using System.Collections.Generic;

namespace ApexGP24;

public struct F1Livery3D
{
    public string Code;
    public string Name;
    public Color Primary;
    public Color Secondary;
    public Color Glove;
}

public partial class PlayerCar3D : Node3D
{
    public static readonly F1Livery3D[] Liveries =
    {
        new() { Code = "AT",  Name = "Alpha White",     Primary = new Color(0.93f, 0.95f, 0.98f), Secondary = new Color(0.07f, 0.16f, 0.36f), Glove = new Color(0.09f, 0.38f, 0.92f) },
        new() { Code = "FER", Name = "Scuderia Rossa",  Primary = new Color(0.86f, 0.07f, 0.10f), Secondary = new Color(0.98f, 0.82f, 0.08f), Glove = new Color(0.78f, 0.08f, 0.10f) },
        new() { Code = "RBR", Name = "Oracle Velocity", Primary = new Color(0.08f, 0.15f, 0.42f), Secondary = new Color(0.88f, 0.06f, 0.08f), Glove = new Color(0.10f, 0.22f, 0.58f) },
        new() { Code = "MCL", Name = "Papaya GP",       Primary = new Color(1.00f, 0.48f, 0.02f), Secondary = new Color(0.10f, 0.12f, 0.16f), Glove = new Color(0.92f, 0.42f, 0.04f) },
        new() { Code = "MER", Name = "Silver Arrows",   Primary = new Color(0.70f, 0.76f, 0.82f), Secondary = new Color(0.00f, 0.84f, 0.76f), Glove = new Color(0.14f, 0.18f, 0.24f) }
    };

    private TrackBuilder3D _track;
    private Camera3D _cockpitCam;
    private Camera3D _tCam;
    private SteeringWheelMfd3D _steeringWheel;
    private DriverArmsIK3D _driverArms;
    private Node3D _frontLeftSteering;
    private Node3D _frontRightSteering;
    private Node3D _frontLeftSpin;
    private Node3D _frontRightSpin;
    private Node3D _rearLeftSpin;
    private Node3D _rearRightSpin;
    private StandardMaterial3D _brakeGlowMat;
    private StandardMaterial3D _primaryPaintMat;
    private StandardMaterial3D _secondaryPaintMat;
    private Label3D _noseTeamLabel;

    public int LiveryIndex { get; private set; } = 0;
    public F1Livery3D CurrentLivery => Liveries[LiveryIndex];

    public bool IsCockpitCamera { get; private set; } = true;
    public float TrackDistance { get; private set; } = 0f;
    public float TotalDistance { get; private set; } = 0f;
    public float LateralOffset { get; private set; } = 0f;
    public float HeadingOffset { get; private set; } = 0f;
    public float SpeedKmh { get; private set; } = 0f;
    public float SteerAngle { get; private set; } = 0f;
    public float BrakePressure { get; private set; } = 0f;
    public float ErsCharge { get; private set; } = 100f;
    public bool ErsEnabled { get; set; } = false;
    public bool IsOffTrack { get; private set; } = false;
    public bool OnKerb { get; private set; } = false;
    public bool InSlipstream { get; private set; } = false;
    public int CurrentPosition { get; set; } = 16;
    public const int TotalLaps = 5;
    public int CurrentLap { get; private set; } = 1;
    public bool RaceFinished { get; private set; } = false;
    public bool IsQualifying { get; set; } = false;
    public bool QualiLapCompleted { get; private set; } = false;
    public float LastQualiTime { get; private set; } = 0f;
    public float CurrentLapTime { get; private set; } = 0f;
    public float BestLapTime { get; private set; } = 999f;

    // Precision Steering Inputs & Settings
    public bool InputLeft { get; set; }
    public bool InputRight { get; set; }
    public float? AnalogSteerTarget { get; set; } = null;
    public bool InputGas { get; set; }
    public bool InputBrake { get; set; }
    public float SteerSensitivity { get; set; } = 1.25f; // 0.80 (Suave) .. 1.55 (Pro)

    private float _wheelRoll = 0f;
    private float _smoothLatG = 0f;
    private float _smoothLongG = 0f;
    private float _smoothBrakeHeat = 0f;
    private float _smoothTireHeat = 0.38f;
    private float _engineRpm = 4200f;
    private float _totalTime = 0f;
    private float _impactLatVel = 0f;

    // Smooth Physics-to-Render Interpolation Pose Buffers (buttery 60/90/120Hz motion!)
    private Vector3 _prevPos;
    private Basis _prevBasis = Basis.Identity;
    private Vector3 _currPos;
    private Basis _currBasis = Basis.Identity;

    public float EngineRpm => _engineRpm;

    public int Gear
    {
        get
        {
            if (SpeedKmh < 82f) return 1;
            if (SpeedKmh < 126f) return 2;
            if (SpeedKmh < 168f) return 3;
            if (SpeedKmh < 208f) return 4;
            if (SpeedKmh < 248f) return 5;
            if (SpeedKmh < 286f) return 6;
            if (SpeedKmh < 320f) return 7;
            return 8;
        }
    }

    public float RpmNormalized => Mathf.Clamp((_engineRpm - 5500f) / 8500f, 0f, 1f);

    public void Initialize(TrackBuilder3D track)
    {
        _track = track;
        BuildCar3D();
        ResetToGrid(12.0f, -2.8f);
    }

    public void ToggleCamera()
    {
        IsCockpitCamera = !IsCockpitCamera;
        _cockpitCam.Current = IsCockpitCamera;
        _tCam.Current = !IsCockpitCamera;
    }

    public void CycleLivery()
    {
        LiveryIndex = (LiveryIndex + 1) % Liveries.Length;
        var liv = CurrentLivery;
        _primaryPaintMat.AlbedoColor = liv.Primary;
        _secondaryPaintMat.AlbedoColor = liv.Secondary;
        _noseTeamLabel.Text = liv.Code;
        _noseTeamLabel.Modulate = liv.Secondary;
        _steeringWheel.UpdateColors(liv.Glove);
        _driverArms.UpdateColors(liv.Secondary, liv.Primary, liv.Glove);
    }

    public void ResetToGrid(float startDist, float startLane)
    {
        TrackDistance = startDist;
        TotalDistance = startDist;
        LateralOffset = startLane;
        HeadingOffset = 0f;
        SpeedKmh = 0f;
        SteerAngle = 0f;
        BrakePressure = 0f;
        ErsCharge = 100f;
        ErsEnabled = false;
        CurrentLap = 1;
        RaceFinished = false;
        QualiLapCompleted = false;
        CurrentLapTime = 0f;
        _smoothLatG = 0f;
        _smoothLongG = 0f;
        _smoothBrakeHeat = 0f;
        _smoothTireHeat = 0.38f;
        _engineRpm = 4200f;
        _impactLatVel = 0f;
        ComputePose(out _currPos, out _currBasis);
        _prevPos = _currPos;
        _prevBasis = _currBasis;
        Position = _currPos;
        Basis = _currBasis;
        SyncDriverArmsIK();
    }

    public void SyncDriverArmsIK()
    {
        if (_driverArms != null && _steeringWheel != null)
        {
            _driverArms.UpdateIK(
                _steeringWheel.GetLeftWristLocalInCar(),
                _steeringWheel.GetRightWristLocalInCar(),
                SteerAngle);
        }
    }

    private void BuildCar3D()
    {
        var liv = CurrentLivery;
        _primaryPaintMat = ProceduralMaterialFactory.CreateCarPaintMaterial(liv.Primary);
        _secondaryPaintMat = ProceduralMaterialFactory.CreateCarPaintMaterial(liv.Secondary);
        var carbonMat = ProceduralMaterialFactory.CreateCarbonMaterial(6.5f);
        var rubberMat = ProceduralMaterialFactory.CreateTireRubberMaterial();
        var sidewallMat = ProceduralMaterialFactory.CreateTireSidewallMaterial(new Color(0.92f, 0.08f, 0.10f));
        var metalMat = ProceduralMaterialFactory.CreateMetalMaterial(new Color(0.84f, 0.88f, 0.94f), 0.22f);
        _brakeGlowMat = ProceduralMaterialFactory.CreateEmissiveMaterial(new Color(1.0f, 0.32f, 0.04f), 0.0f);

        // 1. Sculpted Smooth 3D Monocoque Nosecone
        AddChild(new MeshInstance3D
        {
            Mesh = MeshPrimitives3D.CreateSculptedNoseconeMesh(),
            MaterialOverride = _primaryPaintMat
        });

        _noseTeamLabel = new Label3D
        {
            Text = liv.Code,
            Position = new Vector3(0f, 0.655f, -1.08f),
            RotationDegrees = new Vector3(-82f, 0f, 0f),
            FontSize = 64,
            PixelSize = 0.0022f,
            Modulate = liv.Secondary,
            OutlineSize = 0
        };
        AddChild(_noseTeamLabel);

        // Titanium F1 Pitot Sensor Tree
        AddChild(new MeshInstance3D
        {
            Mesh = new CylinderMesh { TopRadius = 0.003f, BottomRadius = 0.004f, Height = 0.11f, RadialSegments = 8 },
            Position = new Vector3(0.02f, 0.64f, -1.26f),
            MaterialOverride = metalMat
        });
        AddChild(new MeshInstance3D
        {
            Mesh = new BoxMesh { Size = new Vector3(0.052f, 0.004f, 0.005f) },
            Position = new Vector3(0.02f, 0.68f, -1.26f),
            MaterialOverride = metalMat
        });

        // Curved Left & Right Cockpit Shoulders, Sidepods, Mirrors, Front Wing & Suspension
        foreach (float side in new[] { -1f, 1f })
        {
            Vector3[] shoulderCurve =
            {
                new(side * 0.42f, 0.56f, -0.78f),
                new(side * 0.46f, 0.60f, -0.46f),
                new(side * 0.44f, 0.62f, -0.10f),
                new(side * 0.40f, 0.65f, 0.25f)
            };
            AddChild(new MeshInstance3D
            {
                Mesh = MeshPrimitives3D.CreateTubeAlongPath(
                    shoulderCurve,
                    new[] { 0.085f, 0.095f, 0.095f, 0.088f },
                    new[] { 0.09f, 0.11f, 0.12f, 0.11f },
                    20),
                MaterialOverride = _primaryPaintMat
            });

            AddChild(new MeshInstance3D
            {
                Mesh = new BoxMesh { Size = new Vector3(0.46f, 0.32f, 1.75f) },
                Position = new Vector3(side * 0.54f, 0.36f, 0.12f),
                MaterialOverride = _secondaryPaintMat
            });

            Vector3[] stalkPath =
            {
                new(side * 0.44f, 0.60f, -0.76f),
                new(side * 0.53f, 0.67f, -0.78f),
                new(side * 0.60f, 0.69f, -0.78f)
            };
            AddChild(new MeshInstance3D
