    private (Node3D steerPivot, Node3D spinNode) BuildWheelAssembly(
        float side, float radius, float width,
        StandardMaterial3D rubberMat, StandardMaterial3D sidewallMat, StandardMaterial3D carbonMat, bool isFront)
    {
        var steerPivot = new Node3D();
        var spinNode = new Node3D();
        steerPivot.AddChild(spinNode);

        spinNode.AddChild(new MeshInstance3D { Mesh = MeshPrimitives3D.CreateRevolvedTireTread(radius, width, 40), MaterialOverride = rubberMat });
        spinNode.AddChild(new MeshInstance3D { Mesh = MeshPrimitives3D.CreateTireSidewallDisc(radius * 0.85f, side * width * 0.5f, side, 40), MaterialOverride = sidewallMat });
        spinNode.AddChild(new MeshInstance3D { Mesh = MeshPrimitives3D.CreateTireSidewallDisc(radius * 0.85f, -side * width * 0.5f, -side, 40), MaterialOverride = sidewallMat });

        if (isFront)
        {
            steerPivot.AddChild(new MeshInstance3D
            {
                Mesh = new CylinderMesh { TopRadius = radius * 0.54f, BottomRadius = radius * 0.54f, Height = 0.06f, RadialSegments = 16 },
                Position = new Vector3(-side * (width * 0.52f), 0f, 0f),
                RotationDegrees = new Vector3(0f, 0f, 90f),
                MaterialOverride = carbonMat
            });
            steerPivot.AddChild(new MeshInstance3D
            {
                Mesh = new CylinderMesh { TopRadius = radius * 0.44f, BottomRadius = radius * 0.44f, Height = 0.025f, RadialSegments = 16 },
                Position = new Vector3(-side * (width * 0.54f), 0f, 0f),
                RotationDegrees = new Vector3(0f, 0f, 90f),
                MaterialOverride = _brakeGlowMat
            });
            Vector3[] browPath =
            {
                new(-side * (width * 0.54f), radius * 0.12f, -radius * 0.72f),
                new(-side * (width * 0.56f), radius * 0.84f, -radius * 0.44f),
                new(-side * (width * 0.52f), radius * 1.07f,  radius * 0.14f)
            };
            steerPivot.AddChild(new MeshInstance3D
            {
                Mesh = MeshPrimitives3D.CreateTubeAlongPath(browPath, new[] { 0.012f, 0.016f, 0.012f }, new[] { 0.048f, 0.065f, 0.045f }, 8),
                MaterialOverride = carbonMat
            });
        }
        return (steerPivot, spinNode);
    }

    public void StepPhysics(float dt, bool raceStarted, List<RivalCar3D> rivals, F1AudioSynth audio)
    {
        if (_track == null) return;
        _prevPos = _currPos;
        _prevBasis = _currBasis;
        _totalTime += dt;

        bool left = InputLeft || Input.IsKeyPressed(Key.Left) || Input.IsKeyPressed(Key.A);
        bool right = InputRight || Input.IsKeyPressed(Key.Right) || Input.IsKeyPressed(Key.D);
        bool gas = InputGas || Input.IsKeyPressed(Key.Up) || Input.IsKeyPressed(Key.W);
        bool brake = InputBrake || Input.IsKeyPressed(Key.Down) || Input.IsKeyPressed(Key.S);

        // Waiting on starting grid: allow free-revving V6 engine AND live steering wheel + IK arm movement!
        if (!raceStarted)
        {
            float gridSteerTarget = AnalogSteerTarget.HasValue
                ? Mathf.Clamp(AnalogSteerTarget.Value, -1f, 1f)
                : ((right ? 1f : 0f) - (left ? 1f : 0f));
            SteerAngle = Mathf.Lerp(SteerAngle, gridSteerTarget, 1f - Mathf.Exp(-18f * dt));
            _steeringWheel.RotationDegrees = new Vector3(-16f, 0f, -SteerAngle * 58f);
            _frontLeftSteering.Rotation = new Vector3(0f, -SteerAngle * 0.36f, 0f);
            _frontRightSteering.Rotation = new Vector3(0f, -SteerAngle * 0.36f, 0f);
            SyncDriverArmsIK();

            float targetGridRpm = (gas && !brake) ? 12400f : 4200f;
            _engineRpm = Mathf.Lerp(_engineRpm, targetGridRpm, 1f - Mathf.Exp(-10f * dt));
            audio?.UpdateState(_engineRpm, 0f, 1, gas && !brake, brake, false, false, false);
            _steeringWheel.UpdateTelemetry(dt, 0f, 1, CurrentPosition, RpmNormalized, 0f, BestLapTime, ErsCharge, false, false, _smoothTireHeat, _totalTime);
            return;
        }

        float prevSpeed = SpeedKmh;

        // Progressive Carbon-Ceramic Brake Pressure (taps trim speed gently, holding nails heavy braking!)
        BrakePressure = brake ? Mathf.Min(1f, BrakePressure + 2.5f * dt) : 0f;
        if (brake && ErsEnabled) ErsEnabled = false;

        // Slipstream Detection behind rivals (6m..40m ahead in same lane!)
        InSlipstream = false;
        if (SpeedKmh > 140f && !brake && rivals != null)
        {
            for (int i = 0; i < rivals.Count; i++)
            {
                float dz = rivals[i].TotalDistance - TotalDistance;
                if (dz > 5.5f && dz < 42f && Mathf.Abs(rivals[i].LateralOffset - LateralOffset) < 2.2f)
                {
                    InSlipstream = true;
                    break;
                }
            }
        }

        bool ersActive = ErsEnabled && ErsCharge > 1f && gas && !brake;
        if (ersActive)
        {
            ErsCharge = Mathf.Max(0f, ErsCharge - 20f * dt);
            if (ErsCharge <= 1f) ErsEnabled = false;
        }
        else
        {
            float regen = brake ? (12f + 16f * BrakePressure) : 6.5f;
            ErsCharge = Mathf.Min(100f, ErsCharge + regen * dt);
        }

        float slipBonus = InSlipstream ? 16f : 0f;
        float maxSpeed = (ersActive ? 358f : 322f) + slipBonus;
        IsOffTrack = Mathf.Abs(LateralOffset) > TrackBuilder3D.TrackHalfWidth + 0.55f;
        OnKerb = Mathf.Abs(LateralOffset) > TrackBuilder3D.TrackHalfWidth - 0.15f && Mathf.Abs(LateralOffset) <= TrackBuilder3D.TrackHalfWidth + 1.15f;

        if (gas && !brake)
        {
            float accel = (ersActive ? 180f : 128f) + (InSlipstream ? 16f : 0f);
            if (IsOffTrack) accel *= 0.62f;
            SpeedKmh = Mathf.Min(maxSpeed, SpeedKmh + accel * dt);
        }
        else if (brake)
        {
            float shaped = Mathf.Pow(BrakePressure, 1.2f);
            float decel = 65f + 165f * shaped + 40f * shaped * Mathf.Clamp(SpeedKmh / 320f, 0f, 1f);
            SpeedKmh = Mathf.Max(0f, SpeedKmh - decel * dt);
        }
        else
        {
            SpeedKmh = Mathf.Max(0f, SpeedKmh - (36f + SpeedKmh * 0.085f) * dt);
        }

        if (IsOffTrack && SpeedKmh > 138f)
        {
            SpeedKmh = Mathf.Max(138f, SpeedKmh - 42f * dt);
        }

        // =====================================================================
        // PRO-PRECISION HIGH-AUTHORITY F1 STEERING (SOLVES "A VECES NO GIRA"!)
        // =====================================================================
        float sens = Mathf.Clamp(SteerSensitivity, 0.70f, 1.80f);
        float targetSteer = AnalogSteerTarget.HasValue
            ? Mathf.Clamp(AnalogSteerTarget.Value, -1f, 1f)
            : ((right ? 1f : 0f) - (left ? 1f : 0f));

        if (AnalogSteerTarget.HasValue)
        {
            SteerAngle = Mathf.Lerp(SteerAngle, targetSteer, 1f - Mathf.Exp(-30f * dt));
        }
        else
        {
            bool counterSteering = (targetSteer * SteerAngle) < -0.01f;
            float rate = Mathf.Abs(targetSteer) > 0.01f
                ? (counterSteering ? 34f : (13.5f + 8.5f * sens))
                : 26f;
            SteerAngle = Mathf.Lerp(SteerAngle, targetSteer, 1f - Mathf.Exp(-rate * dt));
        }

        TrackSample sample = _track.SampleAtDistance(TrackDistance);
        float vMs = SpeedKmh / 3.6f;
        float speedMoveScale = Mathf.Clamp(SpeedKmh / 5.0f, 0f, 1f);
        float speedFrac = Mathf.Clamp(SpeedKmh / 280f, 0f, 1f);

        // Smart rejoin grip: steering back toward the asphalt retains crisp grip so you never get stuck off-track!
        bool steeringBackIn = IsOffTrack && (SteerAngle * LateralOffset < -0.05f);
        float surfaceGrip = steeringBackIn ? 0.96f : (IsOffTrack ? 0.84f : 1.0f);
        float trailBrakeBite = 1.0f + 0.25f * BrakePressure;
        float sensMult = 0.62f + 0.38f * sens;

        // Real high-downforce F1 lateral acceleration (68..94 m/s^2) -> NEVER understeers helplessly!
        float aLatMax = (68.0f + 26.0f * speedFrac) * surfaceGrip * sensMult * trailBrakeBite;
        float omegaMech = Mathf.Max(vMs, 3.5f) * (0.145f * sensMult * trailBrakeBite) * speedMoveScale;
        float omegaGrip = (aLatMax / Mathf.Max(vMs, 4.0f)) * speedMoveScale;
        float maxYawRate = Mathf.Min(omegaMech, omegaGrip);

        // Smooth speed-adaptive response curve (calm at 320 km/h, razor-sharp in hairpins)
        float expCurve = Mathf.Clamp(1.24f - 0.14f * sens + 0.12f * speedFrac, 0.95f, 1.38f);
        float shapedSteer = Mathf.Sign(SteerAngle) * Mathf.Pow(Mathf.Abs(SteerAngle), expCurve);
        float counterCatch = (SteerAngle * HeadingOffset < -0.004f) ? 1.48f : 1.0f;
        float manualYawRate = shapedSteer * maxYawRate * counterCatch;

        // Natural high-speed corner scrub helps rotate onto apex when holding deep lock
        if (Mathf.Abs(SteerAngle) > 0.60f && SpeedKmh > 135f && !brake)
        {
            SpeedKmh = Mathf.Max(0f, SpeedKmh - (Mathf.Abs(SteerAngle) - 0.60f) * (SpeedKmh / 320f) * 20f * dt);
        }

        float roadYawRate = vMs * sample.Curvature;
        HeadingOffset += (manualYawRate - roadYawRate) * dt;

        // Pneumatic caster self-centering when releasing steering (zero fishtail wobble!)
        if (Mathf.Abs(targetSteer) < 0.01f && SpeedKmh > 6f)
        {
            if (Mathf.Abs(sample.Curvature) < 0.0045f)
            {
                HeadingOffset *= Mathf.Exp(-9.0f * dt);
            }
            else if (HeadingOffset * sample.Curvature > 0f)
            {
                HeadingOffset *= Mathf.Exp(-5.5f * dt);
            }
        }
        HeadingOffset = Mathf.Clamp(HeadingOffset, -0.48f, 0.48f);

        _impactLatVel *= Mathf.Exp(-7.5f * dt);
        LateralOffset += (vMs * Mathf.Sin(HeadingOffset) + _impactLatVel) * dt;

        // Clean barrier boundary (allows immediate turning away without sticking!)
        float maxLat = TrackBuilder3D.BarrierOffset - 1.10f;
        if (Mathf.Abs(LateralOffset) > maxLat)
        {
            float wallSign = Mathf.Sign(LateralOffset);
            LateralOffset = wallSign * maxLat;
            if (HeadingOffset * wallSign > 0f) HeadingOffset = -wallSign * 0.03f;
            SpeedKmh = Mathf.Max(0f, SpeedKmh * 0.88f - 45f * dt);
        }

        // Smooth Wheel-to-Wheel Player vs Rival Collisions
        if (rivals != null)
        {
            for (int i = 0; i < rivals.Count; i++)
            {
                RivalCar3D rv = rivals[i];
                float dz = rv.TotalDistance - TotalDistance;
                float dx = LateralOffset - rv.LateralOffset;
                if (dz > -4.4f && dz < 4.4f && Mathf.Abs(dx) < 2.05f)
                {
                    if (dz > 2.2f && Mathf.Abs(dx) < 1.55f && SpeedKmh > rv.SpeedKmh + 8f)
                    {
                        // Rear-end bump
                        SpeedKmh = Mathf.Max(30f, rv.SpeedKmh - 12f);
                        rv.SpeedKmh = Mathf.Min(345f, rv.SpeedKmh + 10f);
                        float pushDir = dx >= 0f ? 1f : -1f;
                        _impactLatVel += pushDir * 3.2f;
                    }
                    else
                    {
                        // Side-by-side wheel-to-wheel rub
                        float pushDir = dx >= 0f ? 1f : -1f;
                        float overlap = 2.05f - Mathf.Abs(dx);
                        LateralOffset += pushDir * (overlap * 0.65f + 0.05f);
                        rv.LateralOffset -= pushDir * (overlap * 0.35f);
                        _impactLatVel += pushDir * 2.8f;
                        SpeedKmh *= 0.94f;
                    }
                }
            }
        }

        float forwardMove = Mathf.Max(0f, vMs * Mathf.Cos(HeadingOffset)) * dt;
        TrackDistance += forwardMove;
        TotalDistance += forwardMove;
        CurrentLapTime += dt;

        if (TrackDistance >= _track.TotalLength)
        {
            TrackDistance -= _track.TotalLength;
            if (CurrentLapTime > 5.0f && CurrentLapTime < BestLapTime)
            {
                BestLapTime = CurrentLapTime;
            }
            if (IsQualifying)
            {
                LastQualiTime = CurrentLapTime;
                QualiLapCompleted = true;
            }
            else if (CurrentLap >= TotalLaps)
            {
                RaceFinished = true;
            }
            else
            {
                CurrentLap++;
                CurrentLapTime = 0f;
            }
        }

        // Live F1 V6 Engine RPM Calculation & Audio Synth Update
        float[] tops = { 0f, 82f, 126f, 168f, 208f, 248f, 286f, 320f, 368f };
        int g = Gear;
        float gFrac = Mathf.Clamp((SpeedKmh - tops[g - 1]) / Mathf.Max(1f, tops[g] - tops[g - 1]), 0f, 1f);
        float targetRpm = (g == 1 ? (4300f + gFrac * 9000f) : (7900f + gFrac * 5500f)) + (ersActive ? 500f : 0f);
        _engineRpm = Mathf.Lerp(_engineRpm, targetRpm, 1f - Mathf.Exp(-16f * dt));
        audio?.UpdateState(_engineRpm, SpeedKmh, g, gas && !brake, brake, ersActive, OnKerb, IsOffTrack);

        // G-Force Helmet Inertia, Brake Disc Glow & Tire Thermal State
        float rawLatG = Mathf.Clamp((manualYawRate * vMs) / 44f, -1.0f, 1.0f);
        float rawLongG = Mathf.Clamp(((SpeedKmh - prevSpeed) / Mathf.Max(dt, 0.005f)) / 185f, -1.0f, 1.0f);
        _smoothLatG = Mathf.Lerp(_smoothLatG, rawLatG, 1f - Mathf.Exp(-9.0f * dt));
        _smoothLongG = Mathf.Lerp(_smoothLongG, rawLongG, 1f - Mathf.Exp(-8.0f * dt));

        float targetBrakeHeat = (brake && SpeedKmh > 40f) ? Mathf.Clamp(BrakePressure * (SpeedKmh / 220f), 0.30f, 1.0f) : 0f;
        _smoothBrakeHeat = Mathf.Lerp(_smoothBrakeHeat, targetBrakeHeat, 1f - Mathf.Exp(-(targetBrakeHeat > _smoothBrakeHeat ? 6.5f : 1.8f) * dt));
        _brakeGlowMat.EmissionEnergyMultiplier = _smoothBrakeHeat * 4.5f;

        float targetTireHeat = Mathf.Clamp(0.36f + Mathf.Abs(_smoothLatG) * 0.45f + _smoothBrakeHeat * 0.25f, 0.25f, 1.0f);
        _smoothTireHeat = Mathf.Lerp(_smoothTireHeat, targetTireHeat, 1f - Mathf.Exp(-1.2f * dt));

        // Animate 3D Steering Wheel, 4 Spinning Pirelli Wheels & Live MFD Telemetry
        _steeringWheel.RotationDegrees = new Vector3(-16f, 0f, -SteerAngle * 58f);
        _wheelRoll -= vMs * dt / 0.34f;
        _frontLeftSteering.Rotation = new Vector3(0f, -SteerAngle * 0.36f, 0f);
        _frontRightSteering.Rotation = new Vector3(0f, -SteerAngle * 0.36f, 0f);
        _frontLeftSpin.Rotation = new Vector3(_wheelRoll, 0f, 0f);
        _frontRightSpin.Rotation = new Vector3(_wheelRoll, 0f, 0f);
        _rearLeftSpin.Rotation = new Vector3(_wheelRoll * 0.94f, 0f, 0f);
        _rearRightSpin.Rotation = new Vector3(_wheelRoll * 0.94f, 0f, 0f);

        // Authentic Cockpit Camera G-Force Sway, Look-to-Apex, Kerb Rumble & Speed FOV
        float rumbleY = (OnKerb || IsOffTrack) && SpeedKmh > 25f
            ? Mathf.Sin(_totalTime * 44f) * 0.008f
            : Mathf.Sin(_totalTime * 18f) * (SpeedKmh / 358f) * 0.0016f;
        _cockpitCam.Position = new Vector3(-_smoothLatG * 0.022f, 0.745f + rumbleY - _smoothLongG * 0.008f, -0.155f + _smoothLongG * 0.015f);
        _cockpitCam.RotationDegrees = new Vector3(-8.0f + _smoothLongG * 1.4f, -_smoothLatG * 2.8f, _smoothLatG * 2.5f);
        _cockpitCam.Fov = Mathf.Lerp(_cockpitCam.Fov, 70f + (SpeedKmh / 358f) * 10.5f + (ersActive ? 4.5f : 0f), 1f - Mathf.Exp(-6f * dt));

        _steeringWheel.UpdateTelemetry(
            dt,
            SpeedKmh,
            g,
            CurrentPosition,
            RpmNormalized,
            CurrentLapTime,
            BestLapTime,
            ErsCharge,
            ersActive,
            IsOffTrack,
            _smoothTireHeat,
            _totalTime);

        ComputePose(out _currPos, out _currBasis);
    }

    private void ComputePose(out Vector3 pos, out Basis basis)
    {
        TrackSample s = _track.SampleAtDistance(TrackDistance);
        pos = s.Center + s.Right * LateralOffset + Vector3.Up * 0.04f;
        basis = Basis.LookingAt(s.Forward, Vector3.Up).Rotated(Vector3.Up, -HeadingOffset);
    }

    public void ApplyInterpolatedPose(float alpha)
    {
        Position = _prevPos.Lerp(_currPos, alpha);
        Basis = _prevBasis.Slerp(_currBasis, alpha);
        SyncDriverArmsIK();
    }
}

