        _pauseOverlay.AddChild(resumeBtn);

        var restartBtn = new Button { Text = "↻ REINICIAR PARRILLA", Position = new Vector2(236, 52), Size = new Vector2(200, 44) };
        restartBtn.Pressed += () =>
