            TogglePauseMenu();
        };
        _pauseOverlay.AddChild(restartBtn);

        _modeBtn = new Button { Text = "DIRECCIÓN: BOTONES < > (SIN ZONA MUERTA)", Position = new Vector2(24, 108), Size = new Vector2(412, 42) };
        _modeBtn.Pressed += () =>
        {
            ClearTouches();
