            _btnLeft.Visible = !_analogMode;
            _btnRight.Visible = !_analogMode;
            _analogTrack.Visible = _analogMode;
            _modeBtn.Text = _analogMode ? "DIRECCIÓN: DESLIZANTE ANALÓGICA (0–100%)" : "DIRECCIÓN: BOTONES < > (SIN ZONA MUERTA)";
        };
        _pauseOverlay.AddChild(_modeBtn);

        _sensBtn = new Button { Text = $"SENSIBILIDAD: {SensNames[_sensIndex]}", Position = new Vector2(24, 158), Size = new Vector2(412, 42) };
        _sensBtn.Pressed += () =>
        {
            _sensIndex = (_sensIndex + 1) % SensValues.Length;
            _car.SteerSensitivity = SensValues[_sensIndex];
            _sensBtn.Text = $"SENSIBILIDAD: {SensNames[_sensIndex]}";
        };
