        _teamBtn.Pressed += () =>
        {
            _car.CycleLivery();
            _teamBtn.Text = $"EQUIPO: {_car.CurrentLivery.Name}";
        };
        _pauseOverlay.AddChild(_teamBtn);

        _timeBtn = new Button { Text = $"CLIMA: {_raceCtrl.CurrentTimeLabel}", Position = new Vector2(236, 262), Size = new Vector2(200, 42) };
        _timeBtn.Pressed += () =>
        {
            _raceCtrl.CycleTimeOfDay();
            _timeBtn.Text = $"CLIMA: {_raceCtrl.CurrentTimeLabel}";
        };
        _pauseOverlay.AddChild(_timeBtn);

        _qualBtn = new Button { Text = $"GRÁFICOS: {_raceCtrl.CurrentQualityLabel}", Position = new Vector2(24, 314), Size = new Vector2(412, 42) };
        _qualBtn.Pressed += () =>
        {
            _raceCtrl.ToggleQuality();
            _qualBtn.Text = $"GRÁFICOS: {_raceCtrl.CurrentQualityLabel}";
        };
        _pauseOverlay.AddChild(_qualBtn);

        int ext = AssetLoader3D.LoadedExternalAssets.Count;
        var infoLbl = CreateLabel(
            ext > 0
                ? $"APEX GP 24 V8 IK+QUALI • 20 COCHES 3D • ASSETS EXTERNOS: {ext}"
                : "APEX GP 24 V8 IK+QUALI • 20 COCHES 3D • MOTOR PBR + AUDIO V6",
            12,
            new Color(0.55f, 0.85f, 1.0f));
        infoLbl.Position = new Vector2(24, 376);
        infoLbl.Size = new Vector2(412, 30);
        infoLbl.HorizontalAlignment = HorizontalAlignment.Center;
        _pauseOverlay.AddChild(infoLbl);
    }

    private void TogglePauseMenu()
    {
        bool paused = !_pauseOverlay.Visible;
        _pauseOverlay.Visible = paused;
        _raceCtrl.IsPaused = paused;
        if (paused) ClearTouches();
    }

    private void ClearTouches()
    {
        _steerPointerId = -1;
        _brakePointers.Clear();
        _gasPointers.Clear();
        _car.InputLeft = false;
        _car.InputRight = false;
        _car.AnalogSteerTarget = null;
        _car.InputBrake = false;
        _car.InputGas = false;
    }

    private Vector2 ToCanvasCoords(Vector2 screenPos)
    {
        return Transform.AffineInverse() * screenPos;
    }

    public override void _Input(InputEvent @event)
    {
        if (_car == null || _pauseOverlay.Visible || _finishOverlay.Visible) return;

        if (@event is InputEventScreenTouch touch)
        {
            Vector2 pos = ToCanvasCoords(touch.Position);
            if (touch.Pressed)
            {
                HandlePointerDown(touch.Index, pos);
            }
            else
            {
                HandlePointerUp(touch.Index);
            }
        }
        else if (@event is InputEventScreenDrag drag)
        {
            Vector2 pos = ToCanvasCoords(drag.Position);
            HandlePointerMove(drag.Index, pos);
        }
    }

    private void HandlePointerDown(int id, Vector2 pos)
    {
        // Generous expanded hitboxes so fast thumb taps NEVER miss!
        Rect2 steerRect = _steerZone.GetGlobalRect().Grow(22f);
        Rect2 ersRect = _btnErs.GetGlobalRect().Grow(12f);
        Rect2 brakeRect = _btnBrake.GetGlobalRect().Grow(14f);
        Rect2 gasRect = _btnGas.GetGlobalRect().Grow(16f);

        if (steerRect.HasPoint(pos))
        {
            _steerPointerId = id;
            ApplySteerFromPoint(pos);
            return;
        }
        if (ersRect.HasPoint(pos))
        {
            _car.ErsEnabled = !_car.ErsEnabled;
            return;
        }
        if (brakeRect.HasPoint(pos))
        {
            _brakePointers.Add(id);
            SyncPedals();
            return;
        }
        if (gasRect.HasPoint(pos))
        {
            _gasPointers.Add(id);
            SyncPedals();
        }
    }

    private void HandlePointerMove(int id, Vector2 pos)
    {
        // Pointer-locked steering: stays active EVEN if thumb drifts outside the visual border!
        if (id == _steerPointerId)
        {
            ApplySteerFromPoint(pos);
            return;
        }

        // Allow sliding between Brake and Gas cleanly if desired
        if (_brakePointers.Contains(id) || _gasPointers.Contains(id))
        {
            Rect2 brakeRect = _btnBrake.GetGlobalRect().Grow(24f);
            Rect2 gasRect = _btnGas.GetGlobalRect().Grow(24f);
            if (_brakePointers.Contains(id) && !brakeRect.HasPoint(pos) && gasRect.HasPoint(pos))
            {
                _brakePointers.Remove(id);
                _gasPointers.Add(id);
                SyncPedals();
            }
            else if (_gasPointers.Contains(id) && !gasRect.HasPoint(pos) && brakeRect.HasPoint(pos))
            {
                _gasPointers.Remove(id);
                _brakePointers.Add(id);
                SyncPedals();
            }
        }
    }

    private void HandlePointerUp(int id)
    {
        if (id == _steerPointerId)
        {
            _steerPointerId = -1;
            _car.InputLeft = false;
            _car.InputRight = false;
            _car.AnalogSteerTarget = null;
        }
        if (_brakePointers.Remove(id) || _gasPointers.Remove(id))
        {
            SyncPedals();
        }
    }

    private void ApplySteerFromPoint(Vector2 pos)
    {
        Rect2 r = _steerZone.GetGlobalRect();
        float midX = r.Position.X + r.Size.X * 0.5f;
        if (_analogMode)
        {
            float halfTravel = Mathf.Max(20f, r.Size.X * 0.42f);
            float norm = Mathf.Clamp((pos.X - midX) / halfTravel, -1f, 1f);
            float val = Mathf.Abs(norm) < 0.04f ? 0f : norm;
            _car.AnalogSteerTarget = val;
            _car.InputLeft = val < -0.04f;
            _car.InputRight = val > 0.04f;
        }
        else
        {
            // Zero dead gap: left half = Left, right half = Right!
            _car.AnalogSteerTarget = null;
            bool isRight = pos.X >= midX;
            _car.InputLeft = !isRight;
            _car.InputRight = isRight;
        }
    }

    private void SyncPedals()
    {
        _car.InputBrake = _brakePointers.Count > 0;
        _car.InputGas = _gasPointers.Count > 0;
    }

    public override void _Process(double delta)
    {
        if (_car == null) return;

        // Top-Left Qualifying OR Race Info & Mini Leaderboard
        _skipQualiBtn.Visible = _raceCtrl.IsQualifying;
        if (_raceCtrl.IsQualifying)
        {
            _posLbl.Text = $"QUALI • P{_car.CurrentPosition}";
            _lapLbl.Text = $"1 VUELTA • {_car.CurrentLapTime:00.000}s";
            _lbLines.Text = $"POLE {_raceCtrl.PoleReferenceTime:00.000}s\nVTA  {_car.CurrentLapTime:00.000}s\nPROY P{_car.CurrentPosition} / 20";
        }
        else
        {
            _posLbl.Text = $"P{_car.CurrentPosition} / 20";
            string bestStr = _car.BestLapTime < 900f ? $"  •  B {_car.BestLapTime:00.0}" : "";
            _lapLbl.Text = $"VTA {Mathf.Min(_car.CurrentLap, PlayerCar3D.TotalLaps)}/{PlayerCar3D.TotalLaps}  •  {_car.CurrentLapTime:00.00}{bestStr}";
            _lbLines.Text = _raceCtrl.BuildMiniLeaderboardText();
        }

        string hint = _minimap?.UpcomingCornerHint ?? "";
        _cornerCueCard.Visible = _raceCtrl.RaceStarted && !_car.RaceFinished && hint.Length > 0;
        if (_cornerCueCard.Visible) _cornerCueLbl.Text = hint;

        if (_car.RaceFinished && !_finishOverlay.Visible)
        {
            ClearTouches();
            string bestFin = _car.BestLapTime < 900f ? $"{_car.BestLapTime:00.000}s" : "--";
            _finishDetailsLbl.Text = $"POSICIÓN FINAL: P{_car.CurrentPosition} / 20\nMEJOR VUELTA: {bestFin}";
            _finishOverlay.Visible = true;
        }

        // Start Lights Overlay
        if (!_raceCtrl.RaceStarted)
        {
            _startLightsCard.Visible = true;
            int lit = _raceCtrl.StartLightsLitCount;
            for (int i = 0; i < 5; i++)
            {
                _startLightDots[i].Color = i < lit ? new Color(1.0f, 0.08f, 0.14f) : new Color(0.18f, 0.06f, 0.07f);
            }
        }
        else
        {
            _startLightsCard.Visible = false;
        }

        // Top-Right Telemetry
        _speedLbl.Text = $"{(int)_car.SpeedKmh} KM/H";
        _gearLbl.Text = $"G{_car.Gear}";
        _ersLbl.Text = _car.ErsEnabled ? $"ERS BOOST {(int)_car.ErsCharge}%" : $"ERS {(int)_car.ErsCharge}%";
        _offTrackBanner.Visible = _raceCtrl.RaceStarted && _car.IsOffTrack && _car.SpeedKmh > 18f;
        _slipBanner.Visible = _raceCtrl.RaceStarted && _car.InSlipstream;

        float rpm = _car.RpmNormalized;
        _rpmFill.Size = new Vector2(Mathf.Max(6f, 216f * rpm), 8f);
        _rpmFill.Color = rpm > 0.85f ? new Color(0.20f, 0.55f, 1.0f) : (rpm > 0.58f ? new Color(1.0f, 0.16f, 0.20f) : new Color(0.0f, 0.90f, 0.45f));

        // Live Steering Visual Feedback (glowing buttons, analog knob & steering bar!)
        _leftStyle.BgColor = _car.InputLeft ? new Color(0.10f, 0.42f, 0.72f, 0.94f) : new Color(0.08f, 0.14f, 0.24f, 0.78f);
        _rightStyle.BgColor = _car.InputRight ? new Color(0.10f, 0.42f, 0.72f, 0.94f) : new Color(0.08f, 0.14f, 0.24f, 0.78f);

        float ang = Mathf.Clamp(_car.SteerAngle, -1f, 1f);
        float halfBar = 150f;
        float wBar = Mathf.Abs(ang) * halfBar;
        _steerBarFill.Position = new Vector2(ang >= 0f ? 158f : (158f - wBar), 124f);
        _steerBarFill.Size = new Vector2(wBar, 9f);
        if (_analogMode)
        {
            _analogKnob.Position = new Vector2(124f + ang * 116f, 15f);
        }

        // Pedal Visual Feedback
        _gasStyle.BgColor = _car.InputGas ? new Color(0.08f, 0.65f, 0.28f, 0.96f) : new Color(0.07f, 0.36f, 0.18f, 0.84f);
        _brakeStyle.BgColor = _car.InputBrake ? new Color(0.76f, 0.12f, 0.14f, 0.96f) : new Color(0.42f, 0.08f, 0.10f, 0.84f);
        float bh = _car.BrakePressure * 122f;
        _brakeBarFill.Position = new Vector2(4f, 126f - bh);
        _brakeBarFill.Size = new Vector2(108f, bh);
        _ersStyle.BgColor = _car.ErsEnabled ? new Color(0.0f, 0.68f, 0.92f, 0.95f) : new Color(0.06f, 0.24f, 0.44f, 0.84f);
    }

    private static Panel CreateCard(Vector2 pos, Vector2 size, Color bg, Color border)
    {
        var p = new Panel { Position = pos, Size = size, MouseFilter = Control.MouseFilterEnum.Ignore };
        p.AddThemeStyleboxOverride("panel", MakeStyle(bg, border));
        return p;
    }

    private static Panel CreateAnchoredCard(Control parent, float al, float at, float ar, float ab, float ol, float ot, float orr, float ob, Color bg, Color border)
    {
        var p = new Panel
        {
            AnchorLeft = al, AnchorTop = at, AnchorRight = ar, AnchorBottom = ab,
            OffsetLeft = ol, OffsetTop = ot, OffsetRight = orr, OffsetBottom = ob,
            MouseFilter = Control.MouseFilterEnum.Ignore
        };
        p.AddThemeStyleboxOverride("panel", MakeStyle(bg, border));
        parent.AddChild(p);
        return p;
    }

    private static (Panel panel, StyleBoxFlat style) CreateStyledChildPad(Control parent, Vector2 pos, Vector2 size, string text, int fontSize, Color bg, Color border)
    {
        var style = MakeStyle(bg, border);
        var p = new Panel { Position = pos, Size = size, MouseFilter = Control.MouseFilterEnum.Ignore };
        p.AddThemeStyleboxOverride("panel", style);
        var lbl = CreateLabel(text, fontSize, Colors.White);
        lbl.SetAnchorsPreset(Control.LayoutPreset.FullRect);
        lbl.HorizontalAlignment = HorizontalAlignment.Center;
        lbl.VerticalAlignment = VerticalAlignment.Center;
        p.AddChild(lbl);
        parent.AddChild(p);
        return (p, style);
    }

    private static (Panel panel, StyleBoxFlat style) CreateAnchoredControlPad(Control parent, float al, float at, float ar, float ab, float ol, float ot, float orr, float ob, string text, int fontSize, Color bg, Color border)
    {
        var style = MakeStyle(bg, border);
        var p = new Panel
        {
            AnchorLeft = al, AnchorTop = at, AnchorRight = ar, AnchorBottom = ab,
            OffsetLeft = ol, OffsetTop = ot, OffsetRight = orr, OffsetBottom = ob,
            MouseFilter = Control.MouseFilterEnum.Ignore
        };
        p.AddThemeStyleboxOverride("panel", style);
        var lbl = CreateLabel(text, fontSize, Colors.White);
        lbl.SetAnchorsPreset(Control.LayoutPreset.FullRect);
        lbl.HorizontalAlignment = HorizontalAlignment.Center;
        lbl.VerticalAlignment = VerticalAlignment.Center;
        p.AddChild(lbl);
        parent.AddChild(p);
        return (p, style);
    }

    private static StyleBoxFlat MakeStyle(Color bg, Color border)
    {
        return new StyleBoxFlat
        {
            BgColor = bg,
            BorderColor = border,
            BorderWidthLeft = 2, BorderWidthRight = 2, BorderWidthTop = 2, BorderWidthBottom = 2,
            CornerRadiusTopLeft = 12, CornerRadiusTopRight = 12, CornerRadiusBottomLeft = 12, CornerRadiusBottomRight = 12
        };
    }

    private static Label CreateLabel(string text, int fontSize, Color color)
    {
        var lbl = new Label { Text = text, MouseFilter = Control.MouseFilterEnum.Ignore };
        lbl.AddThemeFontSizeOverride("font_size", fontSize);
        lbl.AddThemeColorOverride("font_color", color);
        return lbl;
    }
}

