            new() { Code = "BOR", RearWingSponsor = "SAUBER",   Primary = new(0.10f, 0.13f, 0.17f), Secondary = new(0.04f, 0.90f, 0.44f), Helmet = new(1.00f, 0.84f, 0.06f), TyreCompound = hard, Skill = 0.79f },
            new() { Code = "BOT", RearWingSponsor = "ALFA",     Primary = new(0.84f, 0.08f, 0.22f), Secondary = new(0.12f, 0.14f, 0.18f), Helmet = new(0.24f, 0.76f, 1.00f), TyreCompound = soft, Skill = 0.81f }
        };

