using Godot;
using System;
using System.Collections.Generic;

namespace ApexGP24;

public partial class TrackMinimap2D : Control
{
    private TrackBuilder3D _track;
    private PlayerCar3D _player;
    private List<RivalCar3D> _rivals;

    private Vector2[] _loopPts = Array.Empty<Vector2>();
    private float _minX, _maxX, _minZ, _maxZ;
    private float _scale = 1f;
    private Vector2 _offset = Vector2.Zero;
    private Vector2 _lastSize = Vector2.Zero;

    public string UpcomingCornerHint { get; private set; } = "";

    public void Initialize(TrackBuilder3D track, PlayerCar3D player, List<RivalCar3D> rivals)
    {
        _track = track;
        _player = player;
        _rivals = rivals;
        MouseFilter = MouseFilterEnum.Ignore;
        RebuildProjectedPoints();
    }

    private void RebuildProjectedPoints()
    {
        if (_track == null || _track.Samples.Count < 3) return;
        Vector2 sz = Size;
        if (sz.X < 10f || sz.Y < 10f) sz = new Vector2(156f, 102f);
        _lastSize = sz;

        int n = _track.Samples.Count;
        _minX = float.MaxValue; _maxX = float.MinValue;
        _minZ = float.MaxValue; _maxZ = float.MinValue;

        for (int i = 0; i < n; i++)
        {
            Vector3 c = _track.Samples[i].Center;
            if (c.X < _minX) _minX = c.X;
            if (c.X > _maxX) _maxX = c.X;
            if (c.Z < _minZ) _minZ = c.Z;
            if (c.Z > _maxZ) _maxZ = c.Z;
        }

        const float pad = 12f;
        float spanX = Mathf.Max(1f, _maxX - _minX);
        float spanZ = Mathf.Max(1f, _maxZ - _minZ);
        _scale = Mathf.Min((sz.X - pad * 2f) / spanX, (sz.Y - pad * 2f) / spanZ);
        float drawnW = spanX * _scale;
        float drawnH = spanZ * _scale;
        _offset = new Vector2((sz.X - drawnW) * 0.5f, (sz.Y - drawnH) * 0.5f);

        _loopPts = new Vector2[n + 1];
        for (int i = 0; i < n; i++)
        {
            _loopPts[i] = WorldToMap(_track.Samples[i].Center);
        }
        _loopPts[n] = _loopPts[0];
    }

    private Vector2 WorldToMap(Vector3 worldPos)
    {
        return new Vector2(
            _offset.X + (worldPos.X - _minX) * _scale,
            _offset.Y + (worldPos.Z - _minZ) * _scale);
    }

    public override void _Process(double delta)
    {
        if (_track == null || _player == null) return;
        if (Size.DistanceSquaredTo(_lastSize) > 1f)
        {
            RebuildProjectedPoints();
        }
        ComputeUpcomingCornerHint();
        QueueRedraw();
    }

    private void ComputeUpcomingCornerHint()
    {
        float peakCurv = 0f;
        float signedPeak = 0f;
        for (float look = 30f; look <= 145f; look += 15f)
        {
            TrackSample s = _track.SampleAtDistance(_player.TrackDistance + look);
            float ak = Mathf.Abs(s.Curvature);
            if (ak > peakCurv)
            {
                peakCurv = ak;
                signedPeak = s.Curvature;
            }
        }

        if (peakCurv > 0.015f && _player.SpeedKmh > 75f)
        {
            UpcomingCornerHint = signedPeak > 0f ? "CURVA DER >>" : "<< CURVA IZQ";
        }
        else
        {
            UpcomingCornerHint = "";
        }
    }

    public override void _Draw()
    {
        if (_loopPts.Length < 4 || _track == null || _player == null) return;

        // 1. Track dark casing & crisp white/grey circuit outline
        DrawPolyline(_loopPts, new Color(0.02f, 0.04f, 0.08f, 0.90f), 7.0f, true);
        DrawPolyline(_loopPts, new Color(0.68f, 0.76f, 0.86f, 0.92f), 3.4f, true);

        // 2. Highlight upcoming 190m ahead so player instantly sees what corner comes next!
        const int previewSteps = 16;
        Vector2[] aheadPts = new Vector2[previewSteps];
        float maxCurv = 0f;
        for (int i = 0; i < previewSteps; i++)
        {
            float d = _player.TrackDistance + i * 12.5f;
            TrackSample s = _track.SampleAtDistance(d);
            aheadPts[i] = WorldToMap(s.Center);
            maxCurv = Mathf.Max(maxCurv, Mathf.Abs(s.Curvature));
        }
        Color previewCol = maxCurv > 0.018f
            ? new Color(1.0f, 0.20f, 0.16f, 0.96f)
            : (maxCurv > 0.010f ? new Color(1.0f, 0.82f, 0.10f, 0.95f) : new Color(0.0f, 0.92f, 1.0f, 0.95f));
        DrawPolyline(aheadPts, previewCol, 4.2f, true);

        // 3. Start / Finish Line Marker
        Vector2 sf = _loopPts[0];
        DrawCircle(sf, 4.2f, Colors.White);
        DrawCircle(sf, 2.4f, new Color(0.92f, 0.08f, 0.08f));

        // 4. All 19 Rival Cars live on the circuit
        if (_rivals != null && !_player.IsQualifying)
        {
            for (int i = 0; i < _rivals.Count; i++)
            {
                if (!_rivals[i].Visible) continue;
                TrackSample rs = _track.SampleAtDistance(_rivals[i].TrackDistance);
                Vector2 rp = WorldToMap(rs.Center);
                DrawCircle(rp, 2.5f, new Color(1.0f, 0.36f, 0.32f, 0.92f));
            }
        }

        // 5. Player Car Dot + Directional Arrow
        TrackSample ps = _track.SampleAtDistance(_player.TrackDistance);
        Vector2 pp = WorldToMap(ps.Center);
        Vector2 fwd2 = new Vector2(ps.Forward.X, ps.Forward.Z).Normalized();
        Vector2 perp2 = new Vector2(-fwd2.Y, fwd2.X);

        DrawCircle(pp, 5.4f, Colors.White);
        DrawCircle(pp, 3.8f, new Color(0.06f, 0.96f, 0.45f));
        Vector2[] arrow =
        {
            pp + fwd2 * 8.5f,
            pp + fwd2 * 2.0f + perp2 * 4.0f,
            pp + fwd2 * 2.0f - perp2 * 4.0f
        };
        DrawColoredPolygon(arrow, new Color(0.15f, 1.0f, 0.55f));
    }
}

