using Godot;

namespace ApexGP24;

public partial class DriverArmsIK3D : Node3D
{
    private const float UpperArmLen = 0.34f;
    private const float ForearmLen = 0.32f;

    private struct ArmRig
    {
        public float Side;
        public Vector3 ShoulderPos;
        public Vector3 ElbowHint;
        public MeshInstance3D UpperArm;
        public MeshInstance3D ElbowJoint;
        public MeshInstance3D Forearm;
        public MeshInstance3D WristCuff;
        public MeshInstance3D WristCollar;
    }

    private readonly ArmRig[] _arms = new ArmRig[2];
    private StandardMaterial3D _suitMat;
    private StandardMaterial3D _cuffMat;
    private StandardMaterial3D _collarMat;

    public void BuildArms(Color suitColor, Color stripeColor, Color gloveColor)
    {
        _suitMat = ProceduralMaterialFactory.CreateNomexFabricMaterial(suitColor, true, stripeColor, false);
        _cuffMat = ProceduralMaterialFactory.CreateNomexFabricMaterial(new Color(0.95f, 0.96f, 0.99f), false, null, true);
        _collarMat = ProceduralMaterialFactory.CreateNomexFabricMaterial(gloveColor, false, null, false);

        // High-Resolution Anatomically Tapered 28-Segment Forearm Mesh (Y = -0.5 elbow .. +0.5 wrist)
        var forearmMesh = MeshPrimitives3D.CreateLoftedLimbMesh(new[]
        {
            (0.00f, 0.044f, 0.042f), // Elbow socket
            (0.14f, 0.047f, 0.044f), // Upper forearm muscle fullness
            (0.32f, 0.044f, 0.041f), // Mid-upper forearm
            (0.55f, 0.039f, 0.036f), // Mid forearm taper
            (0.78f, 0.034f, 0.031f), // Lower forearm
            (0.92f, 0.031f, 0.028f), // Pre-cuff taper
            (1.00f, 0.029f, 0.026f)  // Enters cuff cleanly
        }, 28, true);

        // High-Resolution Tapered Upper Arm Mesh (Y = -0.5 shoulder .. +0.5 elbow)
        var upperArmMesh = MeshPrimitives3D.CreateLoftedLimbMesh(new[]
        {
            (0.00f, 0.056f, 0.054f),
            (0.25f, 0.053f, 0.051f),
            (0.55f, 0.049f, 0.047f),
            (0.85f, 0.046f, 0.044f),
            (1.00f, 0.044f, 0.042f)
        }, 24, true);

        // High-Resolution Ribbed Elastic White Nomex Wrist Cuff (overlaps forearm & glove opening seamlessly!)
        var cuffMesh = MeshPrimitives3D.CreateLoftedLimbMesh(new[]
        {
            (0.00f, 0.0335f, 0.0305f),
            (0.20f, 0.0355f, 0.0325f),
            (0.50f, 0.0350f, 0.0320f),
            (0.82f, 0.0335f, 0.0305f),
            (1.00f, 0.0315f, 0.0285f)
        }, 28, true);

        var elbowSphere = new SphereMesh { Radius = 0.044f, Height = 0.086f, RadialSegments = 22, Rings = 10 };
        var wristCollarSphere = new SphereMesh { Radius = 0.032f, Height = 0.060f, RadialSegments = 22, Rings = 10 };

        for (int i = 0; i < 2; i++)
        {
            float side = i == 0 ? -1f : 1f;
            var rig = new ArmRig
            {
                Side = side,
                ShoulderPos = new Vector3(side * 0.210f, 0.44f, -0.02f),
                ElbowHint = new Vector3(side * 0.58f, -0.80f, 0.08f).Normalized(),
                UpperArm = new MeshInstance3D { Mesh = upperArmMesh, MaterialOverride = _suitMat },
                ElbowJoint = new MeshInstance3D { Mesh = elbowSphere, MaterialOverride = _suitMat },
                Forearm = new MeshInstance3D { Mesh = forearmMesh, MaterialOverride = _suitMat },
                WristCuff = new MeshInstance3D { Mesh = cuffMesh, MaterialOverride = _cuffMat },
                WristCollar = new MeshInstance3D { Mesh = wristCollarSphere, MaterialOverride = _collarMat }
            };

            AddChild(rig.UpperArm);
            AddChild(rig.ElbowJoint);
            AddChild(rig.Forearm);
            AddChild(rig.WristCuff);
            AddChild(rig.WristCollar);
            _arms[i] = rig;
        }
    }

    public void UpdateColors(Color suitColor, Color stripeColor, Color gloveColor)
    {
        if (_suitMat != null)
        {
            _suitMat = ProceduralMaterialFactory.CreateNomexFabricMaterial(suitColor, true, stripeColor, false);
            for (int i = 0; i < 2; i++)
            {
                _arms[i].UpperArm.MaterialOverride = _suitMat;
                _arms[i].ElbowJoint.MaterialOverride = _suitMat;
                _arms[i].Forearm.MaterialOverride = _suitMat;
            }
        }
        if (_collarMat != null)
        {
            _collarMat = ProceduralMaterialFactory.CreateNomexFabricMaterial(gloveColor, false, null, false);
            for (int i = 0; i < 2; i++)
            {
                _arms[i].WristCollar.MaterialOverride = _collarMat;
            }
        }
    }

    /// <summary>
    /// Solves exact 2-bone analytical IK from seated shoulders to the rotating steering wheel's live glove wrist anchors!
    /// Guarantees 100% sealed, organic, zero-gap wrists & forearms at ANY steering angle!
    /// </summary>
    public void UpdateIK(Vector3 leftWristLocal, Vector3 rightWristLocal, float steerAngle)
    {
        SolveArm(_arms[0], leftWristLocal, steerAngle);
        SolveArm(_arms[1], rightWristLocal, steerAngle);
    }

    private static void SolveArm(ArmRig rig, Vector3 wristPos, float steerAngle)
    {
        Vector3 shoulder = rig.ShoulderPos;
        Vector3 diff = wristPos - shoulder;
        float dist = diff.Length();
        float maxReach = UpperArmLen + ForearmLen - 0.006f;
        float d = Mathf.Clamp(dist, 0.08f, maxReach);
        Vector3 dir = dist > 0.0001f ? (diff / dist) : Vector3.Forward;

        // Law of cosines for exact elbow position
        float cosA = Mathf.Clamp((UpperArmLen * UpperArmLen + d * d - ForearmLen * ForearmLen) / (2f * UpperArmLen * d), -1f, 1f);
        float along = UpperArmLen * cosA;
        float perp = UpperArmLen * Mathf.Sqrt(Mathf.Max(0f, 1f - cosA * cosA));

        Vector3 hintProj = rig.ElbowHint - dir * rig.ElbowHint.Dot(dir);
        Vector3 bendDir = hintProj.LengthSquared() > 0.0001f ? hintProj.Normalized() : Vector3.Down;
        Vector3 elbow = shoulder + dir * along + bendDir * perp;

        // Place Upper Arm (shoulder -> elbow)
        PlaceLoftedSegment(rig.UpperArm, shoulder, elbow, 0f);
        rig.ElbowJoint.Position = elbow;

        // Place Forearm (elbow -> inside glove wrist socket for 100% airtight continuity at +-60 deg!)
        Vector3 faDir = (wristPos - elbow).Normalized();
        Vector3 wristEnd = wristPos + faDir * 0.018f;
        float twistRad = -steerAngle * 0.35f;
        PlaceLoftedSegment(rig.Forearm, elbow, wristEnd, twistRad);

        // Place Stitched White Nomex Wrist Cuff wrapping cleanly from forearm right into the blue glove opening
        Vector3 cuffStart = wristPos - faDir * 0.046f;
        Vector3 cuffEnd = wristPos + faDir * 0.012f;
        PlaceLoftedSegment(rig.WristCuff, cuffStart, cuffEnd, twistRad);

        // Soft Blue Glove Wrist Collar sealing the wrist socket seamlessly at any steering lock
        rig.WristCollar.Position = wristPos + faDir * 0.018f;
    }

    private static void PlaceLoftedSegment(MeshInstance3D mesh, Vector3 a, Vector3 b, float twistRad)
    {
        Vector3 delta = b - a;
        float len = Mathf.Max(0.005f, delta.Length());
        Vector3 yAxis = delta / len;
        Vector3 refAxis = Mathf.Abs(yAxis.Dot(Vector3.Up)) > 0.94f ? Vector3.Forward : Vector3.Up;
        Vector3 xAxis = refAxis.Cross(yAxis).Normalized();
        Vector3 zAxis = xAxis.Cross(yAxis).Normalized();

        Basis basis = new Basis(xAxis, yAxis, zAxis);
        if (Mathf.Abs(twistRad) > 0.001f)
        {
            basis = basis.Rotated(yAxis, twistRad);
        }
        // Scale local Y by segment length (mesh is unit length [-0.5 .. +0.5] along Y)
        mesh.Position = (a + b) * 0.5f;
        mesh.Basis = basis.ScaledLocal(new Vector3(1f, len, 1f));
    }
}
